async function verifyTurnstileToken(token: string) {
    const secret = process.env.TURNSTILE_SECRET_KEY;

    if (!secret) {
        console.error("Turnstile secret key is not configured");
        return { success: false, error: "Turnstile yapılandırması eksik." };
    }

    if (!token) {
        return { success: false, error: "Robot doğrulaması tamamlanmadı. Lütfen tekrar deneyin." };
    }

    try {
        const formData = new FormData();
        formData.append("secret", secret);
        formData.append("response", token);

        const response = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", {
            method: "POST",
            body: formData,
        });

        const result = await response.json() as { success?: boolean; "error-codes"?: string[] };

        if (!result.success) {
            const codes = result["error-codes"]?.join(", ") || "bilinmeyen";
            console.error("Turnstile verification failed:", codes);
            return { success: false, error: `Robot doğrulaması başarısız (${codes}). Sayfayı yenileyip tekrar deneyin.` };
        }

        return { success: true };
    } catch (err) {
        console.error("Turnstile verification network error:", err);
        return { success: false, error: "Robot doğrulaması yapılamadı (ağ hatası). Lütfen tekrar deneyin." };
    }
}

export async function signupWithEmailOtp(input: SignupWithEmailOtpInput) {
    try {
        const email = input.email.trim().toLowerCase();
        const username = input.username.trim();
        const fullName = input.fullName.trim();

        // ── 1. Basic validation ──
        if (!email || !input.password || !username || !fullName) {
            return { success: false, error: "Lütfen tüm alanları doldurun. [ERR_SIGNUP_001]" };
        }

        if (username.length < 3) {
            return { success: false, error: "Kullanıcı adı en az 3 karakter olmalı. [ERR_SIGNUP_002]" };
        }

        const passwordError = validatePasswordStrength(input.password);
        if (passwordError) {
            return { success: false, error: `${passwordError} [ERR_SIGNUP_003]` };
        }

        // ── 2. Turnstile verification ──
        const turnstile = await verifyTurnstileToken(input.captchaToken);
        if (!turnstile.success) {
            return { success: false, error: `${turnstile.error} [ERR_SIGNUP_004]` };
        }

        // ── 3. Environment check ──
        const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
        const resendApiKey = process.env.RESEND_API_KEY;

        if (!serviceRoleKey || !resendApiKey) {
            console.error("Missing env vars:", { hasServiceRole: !!serviceRoleKey, hasResend: !!resendApiKey });
            return { success: false, error: "Sunucu yapılandırma hatası. Lütfen yöneticiyle iletişime geçin. [ERR_SIGNUP_005]" };
        }

        let supabaseAdmin;
        try {
            supabaseAdmin = createAdminClient();
        } catch (adminErr: any) {
            console.error("Admin client creation failed:", adminErr);
            return { success: false, error: "Sunucu bağlantı hatası. [ERR_SIGNUP_006]" };
        }

        // ── 4. Username uniqueness check ──
        const { data: existingProfile, error: profileError } = await supabaseAdmin
            .from("profiles")
            .select("id")
            .eq("username", username)
            .maybeSingle();

        if (profileError) {
            console.error("Username check DB error:", profileError);
            return { success: false, error: `Kullanıcı adı kontrolünde hata: ${profileError.message} [ERR_SIGNUP_007]` };
        }

        if (existingProfile) {
            return { success: false, error: "Bu kullanıcı adı zaten alınmış. [ERR_SIGNUP_008]" };
        }

        // ── 5. Generate signup link ──
        // generateLink will return an error if email is already registered
        const { data, error } = await supabaseAdmin.auth.admin.generateLink({
            type: "signup",
            email,
            password: input.password,
            options: {
                redirectTo: input.redirectTo,
                data: {
                    username,
                    full_name: fullName,
                    onboarding_completed: false,
                },
            },
        });

        if (error) {
            console.error("generateLink error:", error.message, error);
            const message = error.message || "Bilinmeyen hata";

            if (message.toLowerCase().includes("already") || message.toLowerCase().includes("registered")) {
                return { success: false, error: "Bu e-posta adresi zaten kayıtlı. Giriş yapmayı deneyin. [ERR_SIGNUP_EMAIL_EXISTS]" };
            }
            if (message.toLowerCase().includes("rate") || message.toLowerCase().includes("limit")) {
                return { success: false, error: "Çok fazla kayıt denemesi. Lütfen biraz bekleyin. [ERR_SIGNUP_RATE]" };
            }
            if (message.toLowerCase().includes("password")) {
                return { success: false, error: `Şifre hatası: ${message} [ERR_SIGNUP_PASSWORD]` };
            }

            return { success: false, error: `Kayıt oluşturulamadı: ${message} [ERR_SIGNUP_009]` };
        }

        if (!data?.properties?.email_otp || !data.user) {
            console.error("generateLink returned no OTP or user:", { hasOtp: !!data?.properties?.email_otp, hasUser: !!data?.user });
            return { success: false, error: "Doğrulama kodu oluşturulamadı. Lütfen tekrar deneyin. [ERR_SIGNUP_010]" };
        }

        // If user already has confirmed email, they're already registered
        if (data.user.email_confirmed_at) {
            return { success: false, error: "Bu e-posta adresi zaten kayıtlı. Giriş yapmayı deneyin. [ERR_SIGNUP_EMAIL_EXISTS]" };
        }

        // ── 7. Send verification email ──
        let resend;
        try {
            resend = new Resend(resendApiKey);
        } catch (resendInitErr: any) {
            console.error("Resend init failed:", resendInitErr);
            return { success: false, error: "E-posta servisi başlatılamadı. [ERR_SIGNUP_011]" };
        }

        const result = await resend.emails.send({
            from: "FizikHub <bildirim@fizikhub.com>",
            to: email,
            subject: "FizikHub doğrulama kodun",
            html: buildConfirmationTemplate(data.properties.email_otp),
        });

        if (result.error) {
            console.error("Resend email error:", result.error);
            // Clean up: delete the user since email couldn't be sent
            try {
                await supabaseAdmin.auth.admin.deleteUser(data.user.id);
            } catch (deleteErr) {
                console.error("Failed to cleanup user after email error:", deleteErr);
            }
            return { success: false, error: `Doğrulama e-postası gönderilemedi: ${result.error.message} [ERR_SIGNUP_012]` };
        }

        return { success: true, email };

    } catch (unexpectedError: any) {
        // This is the CRITICAL safety net - catches ANY uncaught exception
        // so Next.js never hides the real error from the client
        console.error("CRITICAL: Unexpected signup error:", unexpectedError);
        const msg = unexpectedError?.message || unexpectedError?.toString() || "Bilinmeyen hata";
        return { success: false, error: `Beklenmeyen sunucu hatası: ${msg} [ERR_SIGNUP_CRITICAL]` };
    }
}

export async function verifyOtp(token: string, type: 'signup' | 'recovery' | 'magiclink' = 'signup', email: string) {
    const supabase = await createClient();

    const { data, error } = await supabase.auth.verifyOtp({
        email,
        token,
        type,
    });

    if (error) {
        return { success: false, error: error.message };
    }

    const verifiedUser = data.user;
    if (!verifiedUser) {
        return { success: false, error: "Oturum doğrulandı ama kullanıcı bilgisi alınamadı." };
    }

    const profileResult = await ensureUserProfile(verifiedUser);
    if (!profileResult.success) {
        console.error("OTP profile ensure error:", profileResult.error);
        return { success: false, error: "Profil hazırlanırken hata oluştu. Lütfen tekrar deneyin." };
    }

    revalidatePath("/", "layout");
    return { success: true };
}

export async function resendOtp(email: string) {
    const normalizedEmail = email.trim().toLowerCase();
    const resendApiKey = process.env.RESEND_API_KEY;

    if (!normalizedEmail) {
        return { success: false, error: "E-posta adresi bulunamadı." };
    }

    if (!resendApiKey) {
        return { success: false, error: "E-posta doğrulama sistemi yapılandırması eksik." };
    }

    const supabaseAdmin = createAdminClient();
    const resendSignupParams = {
        type: "signup",
        email: normalizedEmail,
    } as Parameters<typeof supabaseAdmin.auth.admin.generateLink>[0];
    const { data, error } = await supabaseAdmin.auth.admin.generateLink(resendSignupParams);

    if (error || !data?.properties?.email_otp) {
        return { success: false, error: error?.message || "Yeni doğrulama kodu oluşturulamadı." };
    }

    const resend = new Resend(resendApiKey);
    const result = await resend.emails.send({
        from: "FizikHub <bildirim@fizikhub.com>",
        to: normalizedEmail,
        subject: "FizikHub doğrulama kodun",
        html: buildConfirmationTemplate(data.properties.email_otp),
    });

    if (result.error) {
        return { success: false, error: result.error.message };
    }

    return { success: true };
}

export async function completeOnboarding(formData: FormData) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return { success: false, error: "Kullanıcı bulunamadı." };
    }

    const username = formData.get("username") as string;
    const fullName = formData.get("fullName") as string;
    const avatarUrl = formData.get("avatarUrl") as string;
    const bio = formData.get("bio") as string;

    const updateData: any = {
        onboarding_completed: true,
        has_seen_onboarding: true
    };

    if (username) updateData.username = username;
    if (fullName) updateData.full_name = fullName;
    if (avatarUrl) updateData.avatar_url = avatarUrl;
    if (bio) updateData.bio = bio;

    const { error } = await supabase
        .from('profiles')
        .update(updateData)
        .eq('id', user.id);

    if (error) {
        return { success: false, error: error.message };
    }

    revalidatePath("/", "layout");
    revalidatePath("/profil", "layout");
    return { success: true };
}

export async function signOut() {
    const supabase = await createClient();
    await supabase.auth.signOut();
    revalidatePath("/");
    redirect("/login");
}

export async function getOnboardingStatus() {
    try {
        const supabase = await createClient();
        const { data: { user }, error } = await supabase.auth.getUser();

        if (error || !user) return { shouldShowOnboarding: false };

        const { data: profile } = await supabase
            .from('profiles')
            .select('onboarding_completed, has_seen_onboarding')
            .eq('id', user.id)
            .maybeSingle();

        return {
            shouldShowOnboarding: Boolean(profile?.onboarding_completed && !profile.has_seen_onboarding)
        };
    } catch (error) {
        console.error("Onboarding status check failed:", error);
        return { shouldShowOnboarding: false };
    }
}

import { notFound, permanentRedirect } from "next/navigation";
import { ReadingProgress } from "@/components/blog/reading-progress";
import { createClient } from "@/lib/supabase-server";
import { getArticleBySlug } from "@/lib/api";
import { calculateReadingTime, formatReadingTime } from "@/lib/reading-time";
import { Metadata } from "next";
import { ExperimentViewer } from "@/components/experiment/experiment-viewer";
import { isAdminEmail } from "@/lib/admin";
import { buildMetaDescription, getArticleCanonicalPath, getSiteUrl, isLikelyIndexableArticle, isLikelyIndexableTitle, toAbsoluteUrl } from "@/lib/seo-utils";

interface PageProps {
    params: Promise<{ slug: string }>;
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
    const { slug } = await params;
    const article = await getArticleBySlug(slug);

    if (!article) {
        return {
            title: "Deney Bulunamadı",
            robots: { index: false, follow: true },
        };
    }

    const baseUrl = getSiteUrl();
    const description = buildMetaDescription(
        [article.excerpt, article.summary, article.content],
        `${article.title} deneyini Fizikhub'da adım adım incele.`,
    );
    const imageUrl = toAbsoluteUrl(article.cover_url || (article as { image_url?: string }).image_url, baseUrl) || `${baseUrl}/og-image.jpg`;
    const canonicalPath = getArticleCanonicalPath(article) || `/deney/${article.slug || slug}`;
    const shouldIndex = article.category === 'Deney' && isLikelyIndexableArticle(article);

    return {
        title: article.title,
        description,
        robots: {
            index: shouldIndex,
            follow: true,
        },
        openGraph: {
            title: article.title,
            description,
            type: "article",
            publishedTime: article.created_at,
            authors: ["Fizikhub"],
            images: [imageUrl],
        },
        twitter: {
            card: "summary_large_image",
            title: article.title,
            description,
            images: [imageUrl],
        },
        alternates: {
            canonical: `${baseUrl}${canonicalPath}`,
        },
    };
}

// Enable ISR with 10 minute revalidation
export const revalidate = 600;

export default async function ExperimentPage({ params }: PageProps) {
    const { slug } = await params;
    const supabase = await createClient();
    const article = await getArticleBySlug(slug);

    if (!article) {
        notFound();
    }

    if (article.category !== 'Deney') {
        permanentRedirect(`/makale/${article.slug || slug}`);
    }

    // Get current user
    const { data: { user } } = await supabase.auth.getUser();

    // Group all independent queries into a Promise.all block
    const [
        { count: dbLikeCount },
        { data: userLike },
        { data: userBookmark },
        { data: commentsData },
        { data: relatedArticles }
    ] = await Promise.all([
        supabase.from('article_likes').select('id', { count: 'exact', head: true }).eq('article_id', article.id),
        user ? supabase.from('article_likes').select('id').eq('article_id', article.id).eq('user_id', user.id).single() : Promise.resolve({ data: null }),
        user ? supabase.from('article_bookmarks').select('id').eq('article_id', article.id).eq('user_id', user.id).single() : Promise.resolve({ data: null }),
        supabase.from('article_comments').select('id, content, created_at, parent_comment_id, user_id').eq('article_id', article.id).order('created_at', { ascending: true }),
        supabase.from('articles').select('id, title, slug, excerpt, cover_url, category, created_at, author:author_id(username, full_name)').eq('status', 'published').eq('category', 'Deney').neq('id', article.id).not('slug', 'is', null).order('created_at', { ascending: false }).limit(8)
    ]);

    const likeCount = dbLikeCount;

    // Fetch profiles separately
    const userIds = commentsData?.map(c => c.user_id) || [];
    const { data: profiles } = userIds.length > 0 ? await supabase
        .from('profiles')
        .select('id, username, full_name, avatar_url')
        .in('id', userIds) : { data: [] };

    // Combine comments with profiles
    const comments = commentsData?.map(({ user_id, ...comment }) => {
        const publicProfile = profiles?.find(p => p.id === user_id);

        return {
            ...comment,
            profiles: {
                username: publicProfile?.username || 'unknown',
                full_name: publicProfile?.full_name || null,
                avatar_url: publicProfile?.avatar_url || null,
            },
        };
    }) || [];

    // Check if user is admin
    const isAdmin = isAdminEmail(user?.email);

    // Calculate reading time
    const readingTime = calculateReadingTime(article.content || "");
    const formattedReadingTime = formatReadingTime(readingTime);
    const baseUrl = getSiteUrl();
    const articleUrl = `${baseUrl}/deney/${article.slug}`;
    const description = buildMetaDescription(
        [article.excerpt, article.summary, article.content],
        `${article.title} deneyini Fizikhub'da adım adım incele.`,
    );
    const imageUrl = toAbsoluteUrl(article.cover_url || (article as { image_url?: string }).image_url, baseUrl) || `${baseUrl}/og-image.jpg`;
    const filteredRelatedArticles = (relatedArticles || [])
        .filter((relatedArticle: any) => isLikelyIndexableTitle(relatedArticle.title))
        .slice(0, 3);

    // JSON-LD structured data for Article
    const jsonLd = {
        '@context': 'https://schema.org',
        '@type': 'Article',
        '@id': `${articleUrl}#article`,
        url: articleUrl,
        headline: article.title,
        description,
        image: imageUrl,
        datePublished: article.created_at,
        dateModified: (article as { updated_at?: string }).updated_at || article.created_at,
        author: {
            '@type': 'Person',
            name: article.author?.full_name || article.author?.username || 'Fizikhub Ekibi',
        },
        publisher: {
            '@type': 'Organization',
            name: 'Fizikhub',
            logo: {
                '@type': 'ImageObject',
                url: 'https://www.fizikhub.com/icon-512.png',
            },
        },
        mainEntityOfPage: {
            '@type': 'WebPage',
            '@id': articleUrl,
        },
    };

    return (
        <>
            <script
                type="application/ld+json"
                dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
            />
            <ReadingProgress />

            <ExperimentViewer
                article={article}
                readingTime={formattedReadingTime}
                likeCount={likeCount || 0}
                initialLiked={!!userLike}
                initialBookmarked={!!userBookmark}
                comments={comments || []}
                isLoggedIn={!!user}
                isAdmin={isAdmin}
                userAvatar={user ? (profiles?.find(p => p.id === user.id)?.avatar_url) : undefined}
                relatedArticles={filteredRelatedArticles}
            />
        </>
    );
}

"use server";

import { createClient } from "@/lib/supabase-server";
import { createAdminClient } from "@/lib/supabase-admin";
import { revalidatePath } from "next/cache";
import { createNotification } from "@/app/notifications/actions";
import { getClientMetadata, checkContent } from "@/lib/moderation";
import { isAdminEmail } from "@/lib/admin";

type ReputationParams = {
    p_user_id: string;
    p_points: number;
    p_reason: string;
    p_reference_type: string;
    p_reference_id: number;
};

export async function checkAndAwardBadges(userId: string) {
    try {
        const adminSupabase = createAdminClient();

        // 1. Get user's current reputation
        const profileResult = await adminSupabase
            .from('profiles')
            .select('reputation')
            .eq('id', userId)
            .single();

        const profile = profileResult?.data;
        if (!profile) return;

        const rep = profile.reputation || 0;

        // 2. Get all badges from database
        const badgesQuery = adminSupabase
            .from('badges')
            .select('id, name, requirement_type, requirement_value');

        // Safe chain for order if it exists, otherwise just await the base query
        const badgesResult = await (typeof badgesQuery.order === 'function'
            ? badgesQuery.order('requirement_value', { ascending: true })
            : badgesQuery);

        const badges = badgesResult?.data;
        if (!badges || !Array.isArray(badges)) return;

        // 3. Get badges the user already has
        const userBadgesResult = await adminSupabase
            .from('user_badges')
            .select('badge_id')
            .eq('user_id', userId);

        const userBadges = userBadgesResult?.data;
        const existingBadgeIds = new Set((userBadges || []).map((ub: any) => ub?.badge_id));

        // 4. Check each badge's requirement
        for (const badge of badges) {
            if (!badge || !badge.id || existingBadgeIds.has(badge.id)) continue; // Already has it

            let qualifies = false;
            if (badge.requirement_type === 'reputation') {
                qualifies = rep >= (badge.requirement_value || 0);
            } else if (badge.requirement_type === 'question_count') {
                const result = await adminSupabase
                    .from('questions')
                    .select('id', { count: 'exact', head: true })
                    .eq('author_id', userId);
                qualifies = (result?.count || 0) >= (badge.requirement_value || 0);
            } else if (badge.requirement_type === 'article_count') {
                const result = await adminSupabase
                    .from('articles')
                    .select('id', { count: 'exact', head: true })
                    .eq('author_id', userId)
                    .neq('status', 'draft');
                qualifies = (result?.count || 0) >= (badge.requirement_value || 0);
            } else if (badge.requirement_type === 'accepted_answer_count') {
                const result = await adminSupabase
                    .from('answers')
                    .select('id', { count: 'exact', head: true })
                    .eq('author_id', userId)
                    .eq('is_accepted', true);
                qualifies = (result?.count || 0) >= (badge.requirement_value || 0);
            } else if (badge.requirement_type === 'following_count') {
                const result = await adminSupabase
                    .from('follows')
                    .select('id', { count: 'exact', head: true })
                    .eq('follower_id', userId);
                qualifies = (result?.count || 0) >= (badge.requirement_value || 0);
            } else if (badge.requirement_type === 'follower_count') {
                const result = await adminSupabase
                    .from('follows')
                    .select('id', { count: 'exact', head: true })
                    .eq('following_id', userId);
                qualifies = (result?.count || 0) >= (badge.requirement_value || 0);
            }

            if (qualifies) {
                // Award the badge!
                const insertResult = await adminSupabase
                    .from('user_badges')
                    .insert({
                        user_id: userId,
                        badge_id: badge.id
                    });

                if (!insertResult?.error) {
                    // Create a notification for the badge!
                    await adminSupabase.from('notifications').insert({
                        recipient_id: userId,
                        actor_id: userId,
                        type: 'welcome',
                        resource_type: 'profile',
                        resource_id: userId,
                        content: `Yeni Rozet Kazanıldı: ${badge.name}! 🏆`
                    });
                }
            }
        }
    } catch (err) {
        console.error("[checkAndAwardBadges Error]:", err);
    }
}

async function addReputation(params: ReputationParams) {
    const { error } = await createAdminClient().rpc('add_reputation', params);
    if (error) {
        console.error("Add Reputation Error:", error);
    } else {
        // Automatically check and award badges!
        await checkAndAwardBadges(params.p_user_id);
    }
}

