import { createClient } from "@/lib/supabase-server";
import { redirect } from "next/navigation";
import { getMessages, getReactions, markAsRead, Message } from "../actions";
import { ChatWindow } from "@/components/messaging/chat-window";
import { ChatHeader } from "@/components/messaging/chat-header";

export default async function ConversationPage({
    params,
}: {
    params: Promise<{ id: string }>;
}) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        redirect("/login");
    }

    const { id: conversationId } = await params;

    let messages: Message[] = [];
    let initialReactions: Record<number, { reaction: string; count: number; myReaction: boolean }[]> = {};
    let otherUser: any = null;

    try {
        // Fetch everything in parallel
        const [messagesResult, reactionsResult] = await Promise.all([
            getMessages(conversationId),
            getReactions(conversationId),
            markAsRead(conversationId),
        ]);

        messages = messagesResult.messages;
        initialReactions = reactionsResult;

        // Fetch other participant info with profile in a single query
        const { data: otherParticipant } = await supabase
            .from("conversation_participants")
            .select("user_id, profiles:user_id(id, username, full_name, avatar_url)")
            .eq("conversation_id", conversationId)
            .neq("user_id", user.id)
            .single();

        if (otherParticipant) {
            otherUser = otherParticipant.profiles;
        }
    } catch (e) {
        console.error("Conversation Page: Error fetching data", e);
    }

    return (
        <div className="flex flex-col h-[100dvh] bg-[#050505]">
            {/* Header */}
            <ChatHeader otherUser={otherUser} />

            {/* Chat */}
            <ChatWindow
                key={conversationId}
                conversationId={conversationId}
                initialMessages={messages}
                currentUserId={user.id}
                initialReactions={initialReactions}
                otherUserAvatar={otherUser?.avatar_url}
            />
        </div>
    );
}

"use server";

import { createClient } from "@/lib/supabase-server";
import { createAdminClient } from "@/lib/supabase-admin";
import { revalidatePath } from "next/cache";
import { getClientMetadata, checkContent } from "@/lib/moderation";

// ============================================
// TYPES
// ============================================

export interface Message {
    id: number;
    conversation_id: string;
    sender_id: string;
    content: string;
    is_read: boolean;
    created_at: string;
    message_type: 'text' | 'image' | 'system';
    edited_at: string | null;
    reply_to_id: number | null;
    reply_to?: {
        id: number;
        content: string;
        sender_id: string;
    } | null;
    sender?: {
        id: string;
        username: string;
        full_name: string;
        avatar_url: string;
    } | null;
}

export interface Conversation {
    id: string;
    updated_at: string;
    last_message_preview: string | null;
    last_message_at: string | null;
    last_message_sender_id: string | null;
    otherUser: {
        id: string;
        username: string;
        full_name: string;
        avatar_url: string;
    } | null;
    lastMessage: Message | null;
    unreadCount: number;
}

export interface Reaction {
    id: string;
    message_id: number;
    user_id: string;
    reaction: string;
    created_at: string;
}

// ============================================
// SEND MESSAGE
// ============================================

export async function sendMessage(
    conversationId: string,
    content: string,
    replyToId?: number | null
) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return { success: false, error: "Giriş yapmalısınız" };
    }

    if (!content.trim()) {
        return { success: false, error: "Mesaj boş olamaz" };
    }
    if (content.length > 5000) {
        return { success: false, error: "Mesaj en fazla 5.000 karakter olabilir." };
    }

    const { ip, ua } = await getClientMetadata();
    const modResult = await checkContent(content.trim());

    const insertData: any = {
        conversation_id: conversationId,
        sender_id: user.id,
        content: content.trim(),
        is_read: false,
        message_type: 'text',
        author_ip: ip,
        user_agent: ua,
        is_flagged: modResult.isFlagged
    };

    if (replyToId) {
        insertData.reply_to_id = replyToId;
    }

    const { data: message, error } = await supabase
        .from('messages')
        .insert(insertData)
        .select()
        .single();

    if (error) {
        console.error("Send message error:", error);
        return { success: false, error: error.message };
    }

    revalidatePath('/mesajlar');
    return { success: true, message };
}

// ============================================
// GET CONVERSATIONS (Optimized)
// ============================================

export async function getConversations(): Promise<Conversation[]> {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) return [];

    // Get all conversation IDs for this user
    const { data: participations, error: partError } = await supabase
        .from('conversation_participants')
        .select('conversation_id')
        .eq('user_id', user.id);

    if (partError || !participations || participations.length === 0) return [];

    const conversationIds = participations.map(p => p.conversation_id);

    // Get conversations with preview data (no need to fetch all messages!)
    const { data: conversations, error: convError } = await supabase
        .from('conversations')
        .select('id, updated_at, last_message_preview, last_message_at, last_message_sender_id')
        .in('id', conversationIds)
        .order('last_message_at', { ascending: false, nullsFirst: false });

    if (convError || !conversations) return [];

    // Get other participants separately
    const { data: otherParticipants } = await supabase
        .from('conversation_participants')
        .select('conversation_id, user_id')
        .in('conversation_id', conversationIds)
        .neq('user_id', user.id);

    // Get other participants' profiles in one separate query to avoid join issues
    const { data: allProfiles } = await supabase
        .from('profiles')
        .select('id, username, full_name, avatar_url')
        .in('id', otherParticipants?.map((p: any) => p.user_id) || []);

    const profileMap: Record<string, any> = {};
    if (allProfiles) {
        for (const p of allProfiles) {
            profileMap[p.id] = p;
        }
    }

    // Get unread counts per conversation
    const { data: unreadMessages } = await supabase
        .from('messages')
        .select('conversation_id')
        .in('conversation_id', conversationIds)
        .neq('sender_id', user.id)
        .eq('is_read', false);

    const unreadMap: Record<string, number> = {};
    if (unreadMessages) {
        for (const msg of unreadMessages) {
            unreadMap[msg.conversation_id] = (unreadMap[msg.conversation_id] || 0) + 1;
        }
    }

    return conversations.map(conv => {
        const otherPart = otherParticipants?.find(p => p.conversation_id === conv.id);
        const otherProfile = otherPart ? profileMap[otherPart.user_id] : null;

        return {
            id: conv.id,
            updated_at: conv.updated_at,
            last_message_preview: conv.last_message_preview,
            last_message_at: conv.last_message_at,
            last_message_sender_id: conv.last_message_sender_id,
            otherUser: otherProfile || null,
            lastMessage: conv.last_message_preview ? {
                id: 0,
                conversation_id: conv.id,
                sender_id: conv.last_message_sender_id || '',
                content: conv.last_message_preview,
                is_read: true,
                created_at: conv.last_message_at || conv.updated_at,
                message_type: 'text' as const,
                edited_at: null,
                reply_to_id: null,
            } : null,
            unreadCount: unreadMap[conv.id] || 0,
        };
    });
}

// ============================================
// GET MESSAGES (with pagination & replies)
// ============================================

export async function getMessages(
    conversationId: string,
    limit = 50,
    before?: string
): Promise<{ messages: Message[]; hasMore: boolean }> {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) return { messages: [], hasMore: false };

    // Verify user is part of conversation
    const { data: participation } = await supabase
        .from('conversation_participants')
        .select('id')
        .eq('conversation_id', conversationId)
        .eq('user_id', user.id)
        .single();

    if (!participation) return { messages: [], hasMore: false };

    // Build query
    let query = supabase
        .from('messages')
        .select(`
            id,
            conversation_id,
            sender_id,
            content,
            is_read,
            created_at,
            message_type,
            edited_at,
            reply_to_id
        `)
        .eq('conversation_id', conversationId)
        .order('created_at', { ascending: false })
        .limit(limit + 1); // +1 to check if there are more

    if (before) {
        query = query.lt('created_at', before);
    }

    const { data: messages } = await query;

    if (!messages) return { messages: [], hasMore: false };

    const hasMore = messages.length > limit;
    const sliced = hasMore ? messages.slice(0, limit) : messages;

    // Get reply-to messages if any
    const replyIds = sliced.filter(m => m.reply_to_id).map(m => m.reply_to_id!);
    const replyMap: Record<number, { id: number; content: string; sender_id: string }> = {};

    if (replyIds.length > 0) {
        const { data: replies } = await supabase
            .from('messages')
            .select('id, content, sender_id')
            .in('id', replyIds);

        if (replies) {
            for (const r of replies) {
                replyMap[r.id] = { id: r.id, content: r.content, sender_id: r.sender_id };
            }
        }
    }

    // Get unique sender IDs and fetch profiles
    const senderIds = [...new Set(sliced.map(m => m.sender_id))];
    const profileMap: Record<string, any> = {};

    if (senderIds.length > 0) {
        const { data: profiles } = await supabase
            .from('profiles')
            .select('id, username, full_name, avatar_url')
            .in('id', senderIds);

        if (profiles) {
            for (const p of profiles) {
                profileMap[p.id] = p;
            }
        }
    }

    const enrichedMessages: Message[] = sliced.map(m => ({
        ...m,
        message_type: (m.message_type || 'text') as 'text' | 'image' | 'system',
        reply_to: m.reply_to_id ? (replyMap[m.reply_to_id] || null) : null,
        sender: profileMap[m.sender_id] || null,
    })).reverse(); // Reverse to get chronological order

    return { messages: enrichedMessages, hasMore };
}

