                                    <Image
                                        src={article.cover_url}
                                        alt={bookTitle}
                                        fill
                                        className="object-cover"
                                        priority
                                        fetchPriority="high"
                                        quality={60}
                                        sizes="(max-width: 768px) 128px, (max-width: 1024px) 192px, 33vw"
