// Simple internal component for background animations
// Simple internal component for background animations
function SpaceBackground() {
    const [stars, setStars] = useState<Array<{ width: string, height: string, top: string, left: string, duration: number, delay: number }>>([]);

    useEffect(() => {
        const newStars = Array.from({ length: 120 }, () => ({
            width: `${Math.random() * 2 + 0.5}px`,
            height: `${Math.random() * 2 + 0.5}px`,
            top: `${Math.random() * 100}%`,
            left: `${Math.random() * 100}%`,
            duration: Math.random() * 4 + 3,
            delay: Math.random() * 5
        }));
        setStars(newStars);
    }, []);

    return (
        <div className="fixed inset-0 overflow-hidden pointer-events-none -z-10">
            {stars.map((star, i) => (
                <motion.div
                    key={i}
                    className="absolute bg-foreground/30 rounded-full"
                    style={{
                        width: star.width,
                        height: star.height,
                        top: star.top,
                        left: star.left,
                    }}
                    animate={{ opacity: [0.1, 0.8, 0.1], scale: [1, 1.5, 1] }}
                    transition={{
                        duration: star.duration,
                        repeat: Infinity,
                        ease: "easeInOut",
                        delay: star.delay
                    }}
                />
            ))}
        </div>
    );
}

export function ModernExploreView({
    initialArticles,
    categories,
    currentQuery,
    currentCategory,
    user,
    totalPages,
    currentPage,
    searchQuery
}: ModernExploreViewProps) {

    const router = useRouter();
    const [isPending, startTransition] = useTransition();

    const handleCategoryChange = (category: string) => {
        startTransition(() => {
            const params = new URLSearchParams(window.location.search);
            if (category === "Tümü") {
                params.delete("category");
            } else {
                params.set("category", category);
            }
            // Reset page to 1 on category change
            params.delete("page");
            router.push(`/makale?${params.toString()}`);
        });
    };

    const transformedArticles = initialArticles.map(article => ({
        ...article,
        image_url: article.cover_url || article.image_url,
        summary: article.excerpt || article.summary,
        author: article.profiles ? {
            username: article.profiles.username,
            full_name: article.profiles.full_name,
            avatar_url: article.profiles.avatar_url,
            is_writer: article.profiles.is_writer
        } : null
    }));

    // Helper to get empty state message
    const getEmptyStateContent = () => {
        switch (currentCategory) {
            case "Kitap İncelemesi":
                return {
                    icon: BookReviewCard,
                    title: "Henüz inceleme yok...",
                    desc: "Okuduğun son kitabı anlatmaya ne dersin?",
                    action: "İlk İncelemeyi Yaz",
                    link: "/kitap-inceleme/yeni"
                };
            case "Deney":
                return {
                    icon: ExperimentCard,
                    title: "Laboratuvar sessiz...",
                    desc: "Çılgın bir deney yapıp sonuçlarını paylaş!",
                    action: "Deney Paylaş",
                    link: "/makale/yeni?type=experiment"
                };
            case "Terim":
                return {
                    icon: TermCard,
                    title: "Sözlük boş...",
                    desc: "Bilimsel bir terimi açıklayarak bize öğret.",
                    action: "Terim Ekle",
                    link: "/makale/yeni?type=term"
                };
            default:
                return {
                    icon: Sparkles,
                    title: "Henüz makale yok...",
                    desc: "Bu konuda henüz kimse bir şey yazmamış.",
                    action: "İlk Yazıyı Sen Yaz",
                    link: "/makale/yeni"
                };
        }
    };

    const emptyState = getEmptyStateContent();

    return (
        <div className="min-h-screen bg-transparent pb-20 md:pb-0 relative">
            {/* Removed SpaceBackground & UFO for flat Neo-Brutalist look */}

            <div className="w-full max-w-5xl mx-auto px-4 pt-4 pb-8">
                {/* Intro Section - Hard Box */}
                {/* Share Card - Moves to Top */}
                <div className="relative mb-8 mt-0 z-[5000]">
                    <ShareInputCard user={user} />
                </div>

                {/* Search Input */}
                <div className="mb-6 px-1 max-w-lg mx-auto">
                    <SearchInput />
                </div>

                {/* Categories - Neo-Brutalist Tabs */}
                <div className="flex justify-center mb-10 overflow-x-auto pb-4 no-scrollbar">
                    <div className="inline-flex gap-4 p-2">
                        {categories.map((cat) => {
                            const isActuallyActive = currentCategory === cat || (!currentCategory && cat === "Tümü");

                            return (
                                <div
                                    key={cat}
                                    onClick={() => handleCategoryChange(cat)}
                                    className={cn(
                                        "px-4 py-2 text-xs font-black uppercase tracking-wider cursor-pointer border-[2px] border-black transition-all whitespace-nowrap rounded-md",
                                        isActuallyActive
                                            ? "bg-[#FFC800] text-black shadow-[3px_3px_0px_0px_#000] -translate-y-[1px] transform"
                                            : "bg-white text-black hover:bg-zinc-100 hover:shadow-[3px_3px_0px_0px_#000] hover:-translate-y-[1px]"
                                    )}
                                >
                                    {cat}
                                    {isPending && isActuallyActive && (
                                        <span className="ml-2 inline-block w-2 h-2 bg-black rounded-full animate-bounce" />
                                    )}
                                </div>
                            )
                        })}
                    </div>
                </div>

                {/* Reset Filter Button (Optional - Shows only if a category is selected and user might want to go back to 'mixed' view, though user request implied these 3 are the main views. I'll leave a subtle way to clear if needed, or rely on just switching tabs.) */}
                {/* For now, assuming these 3 are the primary navigation modes. */}

                {/* Feed */}
                <div className={cn("space-y-6 sm:space-y-8 min-h-[400px]", isPending && "opacity-50 transition-opacity duration-300")}>
                    {!initialArticles || initialArticles.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-20 px-4 text-center">
                            <motion.div
                                initial={{ scale: 0.8, opacity: 0 }}
                                animate={{ scale: 1, opacity: 1 }}
                                className="w-24 h-24 mb-6 rounded-full bg-gradient-to-tr from-muted/20 to-muted/5 flex items-center justify-center border border-white/5 relative overflow-hidden"
                            >
                                <div className="absolute inset-0 bg-primary/10 blur-xl animate-pulse" />
                                <Telescope className="w-10 h-10 text-muted-foreground relative z-10" />
                            </motion.div>

                            <h3 className="text-xl font-black text-foreground mb-2">{emptyState.title}</h3>
                            <p className="text-muted-foreground max-w-xs mx-auto mb-8 text-sm">{emptyState.desc}</p>

                            <Link
                                href={emptyState.link}
                                className="group relative inline-flex items-center gap-2 px-8 py-3 rounded-full bg-primary text-primary-foreground font-bold overflow-hidden shadow-lg shadow-primary/25 hover:shadow-primary/40 transition-all hover:scale-105"
                            >
                                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700" />
                                <Sparkles className="w-4 h-4" />
                                <span>{emptyState.action}</span>
                            </Link>
                        </div>
                    ) : (
                        transformedArticles.map((article, idx) => (
                            <motion.div
                                key={article.id}
                                initial={{ opacity: 0, y: 30 }}
                                whileInView={{ opacity: 1, y: 0 }}
                                viewport={{ once: true, margin: "-50px" }}
                                transition={{
                                    delay: idx * 0.05,
                                    duration: 0.4,
                                    ease: "easeOut"
                                }}
                            >
                                {article.category === "Kitap İncelemesi" ? (
                                    <BookReviewCard article={article as never} index={idx} />
                                ) : article.category === "Deney" ? (
                                    <ExperimentCard article={article as never} index={idx} />
                                ) : article.category === "Terim" ? (
                                    <TermCard article={article as never} index={idx} />
                                ) : (
                                    <SocialArticleCard
                                        article={article as never}
                                        index={idx}
                                        variant="community"
                                        initialLikes={0}
                                        initialComments={0}
                                    />
                                )}
                            </motion.div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { createAnswerComment } from "@/app/forum/actions";
import { toast } from "sonner";
import { Send } from "lucide-react";

interface AnswerCommentFormProps {
    answerId: number;
    questionId: number;
    onCommentAdded: (comment: any) => void;
    onCancel: () => void;
}

export function AnswerCommentForm({ answerId, questionId, onCommentAdded, onCancel }: AnswerCommentFormProps) {
    const [content, setContent] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!content.trim()) return;

        setIsSubmitting(true);
        try {
            const result = await createAnswerComment({
                content,
                answerId,
                questionId
            });

            if (result.success && result.data) {
                onCommentAdded(result.data);
                setContent("");
                toast.success("Yorum eklendi");
            } else {
                toast.error(result.error || "Hata oluştu");
            }
        } catch (error) {
            toast.error("Bir hata oluştu");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="mt-2 pl-0 sm:pl-0">
            <div className="flex gap-3">
                <div className="flex-1 relative">
                    <Textarea
                        value={content}
                        onChange={(e) => setContent(e.target.value)}
                        placeholder="Yanıtını yaz..."
                        className="min-h-[40px] text-sm resize-none bg-white dark:bg-[#1a1a1d] border-[2.5px] border-black dark:border-zinc-700 focus-visible:ring-0 focus-visible:ring-offset-0 focus:border-[#FFBD2E] dark:focus:border-[#FFBD2E] transition-all rounded-lg px-3 py-2.5 placeholder:text-neutral-400 dark:placeholder:text-zinc-600 shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.06)] focus:shadow-[3px_3px_0_0_#000] dark:focus:shadow-[3px_3px_0_0_rgba(255,255,255,0.08)] dark:text-zinc-200"
                    />

                    {/* Actions bar */}
                    <div className={content.trim() ? "flex justify-end gap-2 mt-2.5" : "hidden"}>
                        <Button type="button" variant="ghost" size="sm" onClick={onCancel} className="h-8 rounded-lg text-xs font-bold uppercase text-neutral-500 dark:text-zinc-400 hover:bg-neutral-100 dark:hover:bg-zinc-800 border-[2px] border-transparent hover:border-neutral-300 dark:hover:border-zinc-600 transition-all">
                            İptal
                        </Button>
                        <Button type="submit" size="sm" disabled={isSubmitting || !content.trim()} className="h-8 rounded-lg text-xs font-bold uppercase bg-[#FFBD2E] text-black border-[2px] border-black dark:border-zinc-600 shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.06)] active:translate-x-[1px] active:translate-y-[1px] active:shadow-[1px_1px_0_0_#000] hover:bg-[#FFD268] transition-all">
                            {isSubmitting ? "..." : "Yanıtla"}
                        </Button>
                    </div>

                    {/* Pre-submit hint */}
                </div>
            </div>
            {!content.trim() && (
                <div className="flex justify-between items-center mt-2">
                    <span className="text-[10px] text-neutral-400 dark:text-zinc-600 pl-1 font-medium">Markdown desteklenir</span>
                    <div className="flex gap-2">
                        <Button type="button" variant="ghost" size="sm" onClick={onCancel} className="h-7 px-3 rounded-lg text-xs font-bold uppercase text-neutral-400 dark:text-zinc-500 hover:bg-neutral-100 dark:hover:bg-zinc-800 border-[2px] border-transparent hover:border-neutral-300 dark:hover:border-zinc-600 transition-all">
                            İptal
                        </Button>
                        <Button type="submit" size="sm" disabled={isSubmitting || !content.trim()} className="h-7 px-4 rounded-lg text-xs font-bold uppercase bg-neutral-200 dark:bg-zinc-800 text-neutral-400 dark:text-zinc-600 border-[2px] border-neutral-300 dark:border-zinc-700 opacity-60 cursor-not-allowed transition-all">
                            Yanıtla
                        </Button>
                    </div>
                </div>
            )}
        </form>
    );
}

