"use client";

import { useRealtimeComments } from "@/hooks/useRealtimeComments";
import { AnswerCommentList } from "./answer-comment-list";
import { useEffect, useRef } from "react";

interface RealtimeCommentListProps {
    answerId: number;
    initialComments: any[];
    currentUserId?: string;
    currentUserEmail?: string;
    questionId: number;
    onDelete?: (commentId: number) => void;
    onCommentsChange?: (comments: any[]) => void;
}

export function RealtimeCommentList({
    answerId,
    initialComments,
    currentUserId,
    currentUserEmail,
    questionId,
    onDelete,
    onCommentsChange
}: RealtimeCommentListProps) {
    const comments = useRealtimeComments(answerId, initialComments, currentUserId, currentUserEmail);
    const onCommentsChangeRef = useRef(onCommentsChange);

    // Update ref when prop changes
    useEffect(() => {
        onCommentsChangeRef.current = onCommentsChange;
    }, [onCommentsChange]);

    useEffect(() => {
        if (onCommentsChangeRef.current) {
            onCommentsChangeRef.current(comments);
        }
    }, [comments]);

    return (
        <AnswerCommentList
            comments={comments}
            currentUserId={currentUserId}
            currentUserEmail={currentUserEmail}
            questionId={questionId}
            onDelete={(id) => {
                if (onDelete) onDelete(id);
            }}
        />
    );
}

import { createClient } from "@/lib/supabase-server";
import Link from "next/link";
import { MessageSquare, ChevronUp } from "lucide-react";

interface RelatedQuestionsProps {
    currentQuestionId: number;
    category: string;
}

export async function RelatedQuestions({ currentQuestionId, category }: RelatedQuestionsProps) {
    const supabase = await createClient();

    // Fetch 3 related questions from the same category
    const { data: questions } = await supabase
        .from("questions")
        .select(`
            id,
            title,
            votes,
            created_at,
            profiles(username, avatar_url),
            answers(count)
        `)
        .eq("category", category)
        .neq("id", currentQuestionId)
        .order("votes", { ascending: false })
        .limit(3);

    if (!questions || questions.length === 0) return null;

    return (
        <nav aria-label="Benzer sorular" className="pt-6 border-t-[2.5px] border-black/10 dark:border-zinc-800">
            <h3 className="text-base font-black mb-4 flex items-center gap-2 uppercase tracking-tight text-neutral-700 dark:text-zinc-300">
                <span className="text-[#FFBD2E]">📚</span>
                Benzer {category} Soruları
            </h3>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                {questions.map((q: any) => (
                    <Link
                        key={q.id}
                        href={`/forum/${q.id}`}
                        prefetch={false}
                        className="group block p-4 bg-white dark:bg-[#1e1e21] border-[2px] border-black/20 dark:border-zinc-700 rounded-[10px] hover:border-black dark:hover:border-zinc-500 hover:shadow-[3px_3px_0_0_#000] dark:hover:shadow-[3px_3px_0_0_rgba(255,255,255,0.06)] transition-all duration-200 hover:-translate-y-0.5"
                    >
                        {/* Title */}
                        <h4 className="font-bold text-sm line-clamp-2 mb-3 group-hover:text-[#FFBD2E] transition-colors text-foreground">
                            {q.title}
                        </h4>

                        {/* Stats */}
                        <div className="flex items-center gap-3 text-xs font-medium text-neutral-400 dark:text-zinc-500">
                            <div className="flex items-center gap-1">
                                <ChevronUp className="w-3 h-3" />
                                <span>{q.votes || 0}</span>
                            </div>
                            <div className="flex items-center gap-1">
                                <MessageSquare className="w-3 h-3" />
                                <span>{q.answers?.[0]?.count || 0}</span>
                            </div>
                        </div>
                    </Link>
                ))}
            </div>
        </nav>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Copy, Twitter, MessageCircle, X } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

interface ShareDrawerProps {
    url: string;
    title: string;
    children: React.ReactNode;
}

export function ShareDrawer({ url, title, children }: ShareDrawerProps) {
    const [isOpen, setIsOpen] = useState(false);

    // Close on escape key
    useEffect(() => {
        const handleEscape = (e: KeyboardEvent) => {
            if (e.key === "Escape") setIsOpen(false);
        };
        if (isOpen) window.addEventListener("keydown", handleEscape);
        return () => window.removeEventListener("keydown", handleEscape);
    }, [isOpen]);

    // Prevent body scroll when open
    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = "hidden";
        } else {
            document.body.style.overflow = "unset";
        }
        return () => {
            document.body.style.overflow = "unset";
        };
    }, [isOpen]);

    const handleCopy = () => {
        navigator.clipboard.writeText(url);
        toast.success("Bağlantı kopyalandı!");
        setIsOpen(false);
    };

    const handleTwitterShare = () => {
        window.open(`https://twitter.com/intent/tweet?url=${encodeURIComponent(url)}&text=${encodeURIComponent(title)}`, '_blank');
        setIsOpen(false);
    };

    const handleWhatsAppShare = () => {
        window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(title + " " + url)}`, '_blank');
        setIsOpen(false);
    };

    return (
        <>
            <div onClick={() => setIsOpen(true)} className="inline-block cursor-pointer ml-auto sm:ml-0">
                <div className="pointer-events-none">
                    {children}
                </div>
            </div>

            <AnimatePresence>
                {isOpen && (
                    <>
                        {/* Backdrop */}
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            onClick={() => setIsOpen(false)}
                            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100]"
                        />

                        {/* Drawer */}
                        <motion.div
                            initial={{ y: "100%" }}
                            animate={{ y: 0 }}
                            exit={{ y: "100%" }}
                            transition={{ type: "spring", damping: 25, stiffness: 200 }}
                            className="fixed bottom-0 left-0 right-0 z-[101] bg-white dark:bg-[#1e1e21] border-t-[2.5px] border-x-[2.5px] border-black dark:border-zinc-700 rounded-t-[20px] p-6 pb-12 shadow-[0_-4px_0_0_#000] dark:shadow-[0_-4px_0_0_rgba(255,255,255,0.06)] sm:max-w-md sm:mx-auto"
                        >
                            <div className="flex items-center justify-between mb-6">
                                <h3 className="font-[family-name:var(--font-outfit)] text-xl font-black text-black dark:text-white uppercase tracking-tight">
                                    Paylaş
                                </h3>
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    onClick={() => setIsOpen(false)}
                                    className="h-9 w-9 border-[2px] border-black dark:border-zinc-600 rounded-lg bg-neutral-100 dark:bg-zinc-800 hover:bg-[#FFBD2E] hover:text-black shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.06)] transition-all hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-[1px_1px_0_0_#000]"
                                >
                                    <X className="h-4 w-4 stroke-[3px] text-black dark:text-zinc-300" />
                                </Button>
                            </div>

                            <div className="space-y-3">
                                <motion.div whileTap={{ scale: 0.97 }}>
                                    <Button
                                        onClick={handleTwitterShare}
                                        className="w-full h-14 flex items-center justify-start gap-4 px-5 border-[2.5px] border-black dark:border-zinc-600 bg-white dark:bg-zinc-800 hover:bg-neutral-50 dark:hover:bg-zinc-700 rounded-[10px] shadow-[3px_3px_0_0_#000] dark:shadow-[3px_3px_0_0_rgba(255,255,255,0.06)] transition-all text-black dark:text-zinc-200 hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-[2px_2px_0_0_#000]"
                                    >
                                        <div className="bg-black text-white p-1.5 rounded-lg shadow-[2px_2px_0_0_#FFBD2E]">
                                            <Twitter className="h-4 w-4 fill-current" />
                                        </div>
                                        <span className="font-bold uppercase tracking-wider text-sm">X'te Paylaş</span>
                                    </Button>
                                </motion.div>

                                <motion.div whileTap={{ scale: 0.97 }}>
                                    <Button
                                        onClick={handleWhatsAppShare}
                                        className="w-full h-14 flex items-center justify-start gap-4 px-5 border-[2.5px] border-black dark:border-zinc-600 bg-[#4ADE80] hover:bg-[#3ec46f] rounded-[10px] shadow-[3px_3px_0_0_#000] dark:shadow-[3px_3px_0_0_rgba(255,255,255,0.06)] transition-all text-black hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-[2px_2px_0_0_#000]"
                                    >
                                        <div className="bg-white text-black p-1.5 rounded-lg shadow-[2px_2px_0_0_#000]">
                                            <MessageCircle className="h-4 w-4 fill-current" />
                                        </div>
                                        <span className="font-bold uppercase tracking-wider text-sm">WhatsApp'ta Gönder</span>
                                    </Button>
                                </motion.div>

                                <motion.div whileTap={{ scale: 0.97 }}>
                                    <Button
                                        onClick={handleCopy}
                                        className="w-full h-14 flex items-center justify-start gap-4 px-5 border-[2.5px] border-black dark:border-zinc-600 bg-[#FFBD2E] hover:bg-[#FFD268] rounded-[10px] shadow-[3px_3px_0_0_#000] dark:shadow-[3px_3px_0_0_rgba(255,255,255,0.06)] transition-all text-black hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-[2px_2px_0_0_#000]"
                                    >
                                        <div className="bg-black text-white p-1.5 rounded-lg shadow-[2px_2px_0_0_#fff]">
                                            <Copy className="h-4 w-4 stroke-[3px]" />
                                        </div>
                                        <span className="font-bold uppercase tracking-wider text-sm">Bağlantıyı Kopyala</span>
                                    </Button>
                                </motion.div>
                            </div>
                        </motion.div>
                    </>
                )}
            </AnimatePresence>
        </>
    );
}

"use client";

import { useState } from "react";
import { m as motion, AnimatePresence, useScroll, useMotionValueEvent } from "framer-motion";
import { MessageSquare, Share2, ChevronUp } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

interface StickyActionBarProps {
    questionId: number;
    votes: number;
    hasVoted: boolean;
    onVote?: () => void;
}

export function StickyActionBar({ questionId, votes, hasVoted }: StickyActionBarProps) {
    const [isVisible, setIsVisible] = useState(false);
    const { scrollY } = useScroll();

    useMotionValueEvent(scrollY, "change", (latest) => {
        const previous = scrollY.getPrevious() ?? 0;

        // Show after scrolling down 300px
        if (latest > 300) {
            if (latest < previous) {
                // Scrolling up -> show
                setIsVisible(true);
            } else if (latest > previous && latest > 300) {
                // Scrolling down -> hide
                setIsVisible(false);
            }
        } else {
            setIsVisible(false);
        }
    });

    const scrollToAnswerForm = () => {
        const form = document.getElementById("answer-form");
        if (form) {
            form.scrollIntoView({ behavior: "smooth", block: "center" });
        }
    };

    const handleShare = async () => {
        const url = window.location.href;
        if (navigator.share) {
            try {
                await navigator.share({ url, title: document.title });
            } catch {
                // User cancelled
            }
        } else {
            await navigator.clipboard.writeText(url);
            toast.success("Link kopyalandı!");
        }
    };

    return (
        <AnimatePresence>
            {isVisible && (
                <motion.div
                    initial={{ y: 100, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    exit={{ y: 100, opacity: 0 }}
                    transition={{ type: "spring", stiffness: 400, damping: 30 }}
                    className="fixed bottom-6 sm:bottom-10 left-0 right-0 z-40 md:hidden px-4 pb-2"
                >
                    <div className="bg-white dark:bg-[#1e1e21] border-[2.5px] border-black dark:border-zinc-700 rounded-[10px] shadow-[4px_4px_0_0_#000] dark:shadow-[4px_4px_0_0_rgba(255,255,255,0.08)] flex items-center justify-between px-3 py-3 gap-2">
                        {/* Vote Display */}
                        <div className={cn(
                            "flex items-center gap-1.5 px-3 py-2 text-sm font-black border-[2px] border-black dark:border-zinc-600 rounded-lg shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.06)]",
                            hasVoted ? "bg-[#FFBD2E] text-black" : "bg-neutral-100 dark:bg-zinc-800 text-black dark:text-white"
                        )}>
                            <ChevronUp className="w-5 h-5 stroke-[3px]" />
                            <span className="text-base">{votes}</span>
                        </div>

                        {/* Share Button */}
                        <button
                            onClick={handleShare}
                            className="p-3 border-[2px] border-black dark:border-zinc-600 rounded-lg bg-white dark:bg-zinc-800 text-black dark:text-zinc-300 shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.06)] hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-[1px_1px_0_0_#000] transition-all"
                        >
                            <Share2 className="w-5 h-5 stroke-[2.5px]" />
                        </button>

                        {/* Answer Button - Primary CTA */}
                        <button
                            onClick={scrollToAnswerForm}
                            className="flex-1 flex items-center justify-center gap-2 px-6 py-2.5 border-[2.5px] border-black dark:border-zinc-600 bg-[#FFBD2E] text-black rounded-lg font-black tracking-wider uppercase text-sm shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.06)] hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-[1px_1px_0_0_#000] transition-all"
                        >
                            <MessageSquare className="w-5 h-5 stroke-[2.5px]" />
                            <span>Cevap Yaz</span>
                        </button>
                    </div>
                </motion.div>
            )}
        </AnimatePresence>
    );
}

"use client";

import { useState } from "react";
import { ArrowUp } from "lucide-react";
import { m as motion, AnimatePresence } from "framer-motion";
import { voteQuestion } from "@/app/forum/actions";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { useUiSounds } from "@/hooks/use-ui-sounds";

interface VoteButtonProps {
    questionId: number;
    initialVotes: number;
    initialHasVoted?: boolean;
    className?: string;
    startExpanded?: boolean;
}

export function VoteButton({ questionId, initialVotes, initialHasVoted = false, className, startExpanded = false }: VoteButtonProps) {
    const [votes, setVotes] = useState(initialVotes);
    const [isVoting, setIsVoting] = useState(false);
    const [hasVoted, setHasVoted] = useState(initialHasVoted);
    const { playInteractSound } = useUiSounds();

    const handleVote = async (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();

        if (isVoting) return;

        // Optimistic update
        const newVotes = hasVoted ? votes - 1 : votes + 1;
        setVotes(newVotes);
        setHasVoted(!hasVoted);
        setIsVoting(true);
        playInteractSound();

        try {
            const result = await voteQuestion(questionId, 1);
            if (!result.success) {
                setVotes(votes);
                setHasVoted(hasVoted);
                if (result.error === "Giriş yapmalısınız.") {
                    toast.error("Oy vermek için giriş yapmalısınız.");
                } else {
                    toast.error("Bir hata oluştu.");
                }
            }
        } catch (error) {
            setVotes(votes);
            setHasVoted(hasVoted);
            toast.error("Bağlantı hatası.");
        } finally {
            setIsVoting(false);
        }
    };

    return (
        <motion.button
            onClick={handleVote}
            whileTap={{ scale: 0.92 }}
            className={cn(
                "flex items-center gap-1.5 px-3 h-9 rounded-lg transition-all duration-200 border-[2px] font-bold text-sm",
                hasVoted
                    ? "bg-[#FFBD2E] text-black border-black dark:border-zinc-600 shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.08)]"
                    : "bg-white dark:bg-zinc-800 text-black dark:text-zinc-300 border-black dark:border-zinc-600 shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.08)] hover:bg-[#FFBD2E]/20",
                "hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-[1px_1px_0_0_#000] dark:hover:shadow-[1px_1px_0_0_rgba(255,255,255,0.06)]",
                className
            )}
            title="Bu soruyu faydalı bulduysan oy ver"
        >
            <AnimatePresence mode="wait">
                <motion.div
                    key={hasVoted ? "voted" : "not-voted"}
                    initial={{ scale: 0.8, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    exit={{ scale: 0.8, opacity: 0 }}
                    transition={{ duration: 0.15 }}
                >
                    <ArrowUp className={cn("h-4 w-4", hasVoted ? "stroke-[3px]" : "stroke-[2.5px]")} />
                </motion.div>
            </AnimatePresence>

            <motion.span
                key={votes}
                initial={{ y: 5, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                className="tabular-nums"
            >
                {votes}
            </motion.span>
        </motion.button>
    );
}

