"use client";

import { m as motion, AnimatePresence } from "framer-motion";
import { X, ChevronLeft, ChevronRight, Trash2, Loader2 } from "lucide-react";
import Image from "next/image";
import { useState, useEffect, useCallback } from "react";
import { createPortal } from "react-dom";
import { createBrowserClient } from "@supabase/ssr";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

interface Story {
    id: string;
    title: string;
    image: string;
    content: string;
    author: string;
    author_id?: string;
}

interface StoryViewerProps {
    stories: Story[];
    initialIndex: number;
    isOpen: boolean;
    onClose: () => void;
}

export function StoryViewer({ stories: initialStories, initialIndex, isOpen, onClose }: StoryViewerProps) {
    // Local state to handle deletions immediately
    const [stories, setStories] = useState(initialStories);
    const [currentIndex, setCurrentIndex] = useState(initialIndex);
    const [progress, setProgress] = useState(0);
    const [mounted, setMounted] = useState(false);
    const [userId, setUserId] = useState<string | null>(null);
    const [isDeleting, setIsDeleting] = useState(false);
    const [isPaused, setIsPaused] = useState(false);

    const STORY_DURATION = 5000; // 5 seconds per story

    const supabase = createBrowserClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    );
    const router = useRouter();

    useEffect(() => {
        setStories(initialStories);
        setCurrentIndex(initialIndex);
    }, [initialStories, initialIndex]);

    useEffect(() => {
        setMounted(true);
        const getUser = async () => {
            const { data: { user } } = await supabase.auth.getUser();
            setUserId(user?.id || null);
        };
        getUser();

        return () => setMounted(false);
    }, []);

    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = "hidden";
        } else {
            document.body.style.overflow = "auto";
        }
        return () => {
            document.body.style.overflow = "auto";
        };
    }, [isOpen]);

    const nextStory = useCallback(() => {
        if (currentIndex < stories.length - 1) {
            setCurrentIndex(prev => prev + 1);
            setProgress(0);
        } else {
            onClose();
        }
    }, [currentIndex, stories.length, onClose]);

    const prevStory = useCallback(() => {
        if (currentIndex > 0) {
            setCurrentIndex(prev => prev - 1);
            setProgress(0);
        }
    }, [currentIndex]);

    const handleDelete = async () => {
        const currentStory = stories[currentIndex];
        if (!currentStory?.id || !userId) return; // Should not happen if button is visible

        // Use a custom toast based confirmation or simple double check could be better, 
        // but for "premium" feel let's use a non-blocking UI or a toast action. 
        // For now, let's keep it simple but safe:
        // We will use a toast that requires a second click or a custom UI state. 
        // Actually, let's just use the `sonner` toast with an action button if possible, 
        // or a small discrete overlay. 
        // Since we are inside a full screen viewer, a native confirm is jarring.
        // Let's implement a "Click again to delete" pattern on the button itself.

        // For this first step, let's just remove the native confirm and handle it in the UI button
        // (We will modify the button in the JSX to handle "Are you sure?")

        try {
            setIsDeleting(true);
            const { error } = await supabase
                .from('stories')
                .delete()
                .eq('id', currentStory.id)
                .eq('author_id', userId); // Extra safety

            if (error) throw error;

            toast.success("Hikaye silindi.");

            // Remove from local list
            const newStories = stories.filter(s => s.id !== currentStory.id);
            if (newStories.length === 0) {
                onClose();
            } else {
                setStories(newStories);
                if (currentIndex >= newStories.length) {
                    setCurrentIndex(newStories.length - 1);
                }
                setProgress(0);
            }
            router.refresh();

        } catch (error: any) {
            toast.error("Silme işlemi başarısız oldu.");
            console.error(error);
        } finally {
            setIsDeleting(false);
        }
    };

    useEffect(() => {
        if (!isOpen || stories.length === 0 || isPaused) return;

        const interval = setInterval(() => {
            setProgress(prev => {
                if (prev >= 100) {
                    nextStory();
                    return 0;
                }
                return prev + (100 / (STORY_DURATION / 100));
            });
        }, 100);

        return () => clearInterval(interval);
    }, [isOpen, currentIndex, nextStory, stories.length, isPaused]);

    if (!isOpen || !mounted || stories.length === 0) return null;

    const currentStory = stories[currentIndex];
    const isOwner = userId && currentStory.author_id === userId;

    const content = (
        <AnimatePresence>
            <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="fixed inset-0 z-[99999] bg-black sm:bg-black/95 sm:backdrop-blur-sm flex items-center justify-center p-0 sm:p-4"
            >
                <div
                    className="relative w-full h-[100dvh] sm:h-[95vh] sm:max-w-[calc(95vh*860/1280)] sm:aspect-[860/1280] sm:rounded-[2rem] rounded-none overflow-hidden bg-black flex flex-col sm:border sm:border-white/10 shadow-2xl mx-auto"
                    onMouseDown={() => setIsPaused(true)}
                    onMouseUp={() => setIsPaused(false)}
                    onTouchStart={() => setIsPaused(true)}
                    onTouchEnd={() => setIsPaused(false)}
                >

                    {/* Progress Bars */}
                    <div className="absolute top-0 left-0 right-0 z-[100] pt-4 flex gap-1 px-2 sm:px-6 pointer-events-none">
                        {stories.map((_, index) => (
                            <div key={index} className="h-0.5 flex-1 bg-white/30 rounded-full overflow-hidden">
                                <motion.div
                                    className="h-full bg-white"
                                    initial={{ width: 0 }}
                                    animate={{
                                        width: index === currentIndex ? `${progress}%` : index < currentIndex ? "100%" : "0%"
                                    }}
                                    transition={{ duration: index === currentIndex ? 0.1 : 0 }}
                                />
                            </div>
                        ))}
                    </div>

                    {/* Header */}
                    <div className="absolute top-8 left-0 right-0 z-[100] px-4 sm:px-6 flex items-center justify-between pointer-events-none">
                        <div className="flex items-center gap-2 pointer-events-auto">
                            <div className="w-8 h-8 rounded-full p-[1.5px] bg-gradient-to-tr from-yellow-400 to-orange-500">
                                <div className="w-full h-full rounded-full bg-zinc-800 overflow-hidden relative border border-black/50">
                                    <Image src={currentStory.image} alt={`${currentStory.title} profil`} fill sizes="(max-width: 640px) 150px, 300px" className="object-cover" />
                                </div>
                            </div>
                            <div className="flex flex-col">
                                <span className="text-white font-black text-xs uppercase tracking-tight drop-shadow-md leading-none">
                                    {currentStory.title}
                                </span>
                                <span className="text-white/60 text-[9px] uppercase font-bold tracking-widest mt-0.5">
                                    {currentStory.author || "FizikHub"}
                                </span>
                            </div>
                        </div>
                        <div className="flex items-center gap-2 pointer-events-auto">
                            {isOwner && (
                                <DeleteStoryButton
                                    onConfirm={handleDelete}
                                    isDeleting={isDeleting}
                                />
                            )}
                            <button
                                onClick={onClose}
                                aria-label="Hikayeyi kapat"
                                className="w-8 h-8 flex items-center justify-center bg-white/10 backdrop-blur-xl border border-white/20 rounded-full text-white hover:bg-white/20 transition-all active:scale-95 z-[101]"
                            >
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                    </div>

                    {/* Story Content */}
                    <div className="flex-1 relative">
                        <Image
                            src={currentStory.image}
                            alt={currentStory.title}
                            fill
                            className="object-cover"
                            priority
                            draggable={false}
                        />

                        {/* Dark Gradients Overlay for Legibility */}
                        <div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-black via-black/40 to-transparent pointer-events-none" />
                        <div className="absolute inset-x-0 top-0 h-32 bg-gradient-to-b from-black/60 to-transparent pointer-events-none z-[90]" />

                        {/* Tap Zones for Navigation */}
                        <div className="absolute inset-y-0 left-0 w-1/2 z-10" onClick={!isPaused ? prevStory : undefined} />
                        <div className="absolute inset-y-0 right-0 w-1/2 z-10" onClick={!isPaused ? nextStory : undefined} />

                        {/* Navigation Arrows (Visible on Desktop) */}
                        <div className="absolute inset-y-0 left-4 hidden sm:flex items-center z-50">
                            <button onClick={prevStory} disabled={currentIndex === 0} aria-label="Önceki hikaye" className="p-2 rounded-full bg-black/30 text-white hover:bg-black/50 transition-colors disabled:opacity-0">
                                <ChevronLeft className="w-8 h-8" />
                            </button>
                        </div>
                        <div className="absolute inset-y-0 right-4 hidden sm:flex items-center z-50">
                            <button onClick={nextStory} aria-label="Sonraki hikaye" className="p-2 rounded-full bg-black/30 text-white hover:bg-black/50 transition-colors">
                                <ChevronRight className="w-8 h-8" />
                            </button>
                        </div>

                        {/* Text Overlay */}
                        <div className="absolute inset-0 z-20 flex flex-col justify-end p-6 sm:p-10 pointer-events-none">
                            <motion.div
                                initial={{ opacity: 0, y: 30 }}
                                animate={{ opacity: 1, y: 0 }}
                                key={currentIndex}
                                className="space-y-3 max-w-sm pointer-events-auto"
                            >
                                {currentStory.title && (
                                    <h2 className="text-3xl sm:text-4xl font-black text-white uppercase tracking-tighter leading-tight drop-shadow-[0_2px_10px_rgba(0,0,0,0.8)]">
                                        {currentStory.title}
                                    </h2>
                                )}
                                {currentStory.content && (
                                    <p className="text-white/95 text-sm sm:text-base leading-snug font-medium drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] font-grotesk tracking-wide max-w-[95%]">
                                        {currentStory.content}
                                    </p>
                                )}
                            </motion.div>
                        </div>
                    </div>
                </div>
            </motion.div>
        </AnimatePresence>
    );

    return createPortal(content, document.body);
}

function DeleteStoryButton({ onConfirm, isDeleting }: { onConfirm: () => void, isDeleting: boolean }) {
    const [confirming, setConfirming] = useState(false);

    useEffect(() => {
        if (confirming) {
            const timer = setTimeout(() => setConfirming(false), 3000);
            return () => clearTimeout(timer);
        }
    }, [confirming]);

    return (
        <button
            onClick={(e) => {
                e.stopPropagation();
                if (confirming) {
                    onConfirm();
                } else {
                    setConfirming(true);
                    toast.warning("Silmek için tekrar dokun.", { duration: 2000 });
                }
            }}
            disabled={isDeleting}
            className={cn(
                "h-10 flex items-center justify-center bg-black/50 backdrop-blur-xl border border-white/10 rounded-full transition-all active:scale-95 z-[101]",
                confirming ? "w-auto px-4 bg-red-500/80 text-white" : "w-10 text-red-500 hover:bg-red-500/20"
            )}
        >
            {isDeleting ? (
                <Loader2 className="w-5 h-5 animate-spin" />
            ) : confirming ? (
                <span className="text-xs font-bold whitespace-nowrap">SİL?</span>
            ) : (
                <Trash2 className="w-5 h-5" />
            )}
        </button>
    );
}

"use client";

import dynamic from "next/dynamic";
import { useEffect, useRef, useState, useCallback } from "react";
import { NeoArticleCard } from "@/components/articles/neo-article-card";
import { createClient } from "@/lib/supabase";
import { processFeedData } from "@/lib/feed-helpers";
import { ArrowUp, RefreshCw } from "lucide-react";

// Lazy load non-critical feed cards to minimize initial JS bundle size and TBT
const QuestionCard = dynamic(() => import("@/components/forum/question-card").then(mod => mod.QuestionCard));
const ExperimentCard = dynamic(() => import("@/components/experiment/experiment-card").then(mod => mod.ExperimentCard));
const BookReviewCard = dynamic(() => import("@/components/book-review/book-review-card").then(mod => mod.BookReviewCard));
const TermCard = dynamic(() => import("@/components/term/term-card").then(mod => mod.TermCard));

const SuggestedUsersCard = dynamic(() => import("@/components/home/suggested-users-card").then(mod => mod.SuggestedUsersCard), {
    loading: () => <div className="h-40 bg-muted/20 animate-pulse rounded-2xl" />
});

// Lazy load heavy injected components
const CommunityInviteBanner = dynamic(() => import("@/components/explore/community-invite-banner").then(mod => mod.CommunityInviteBanner), {
    loading: () => <div className="h-40 bg-muted/20 animate-pulse rounded-2xl" />
});

const QuestionOfTheWeek = dynamic(() => import("@/components/forum/question-of-the-week").then(mod => mod.QuestionOfTheWeek), {
    loading: () => <div className="h-40 bg-muted/20 animate-pulse rounded-2xl" />
});

import { Article, Question } from "@/lib/api";

// Dynamic Loader Skeleton for pagination
const DynamicSkeleton = () => (
    <div className="w-full h-64 bg-white dark:bg-[#1e1e21] border-[3px] border-black dark:border-zinc-700 rounded-[10px] shadow-[4px_4px_0px_0px_#000] p-6 space-y-4 animate-pulse">
        <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-muted/30" />
            <div className="space-y-2 flex-1">
                <div className="h-3 w-1/4 bg-muted/30 rounded" />
                <div className="h-2 w-1/6 bg-muted/30 rounded" />
            </div>
        </div>
        <div className="h-4 w-3/4 bg-muted/30 rounded" />
        <div className="h-16 w-full bg-muted/20 rounded" />
    </div>
);

// ─── STABLE TYPE DEFINITIONS ─────────────────────────────────────
export interface FeedAuthor {
    full_name?: string | null;
    username?: string | null;
    avatar_url?: string | null;
    is_writer?: boolean | null;
    is_verified?: boolean | null;
}

export type FeedArticleData = Article & {
    likes_count?: number;
    comments_count?: number;
    is_liked?: boolean;
    is_bookmarked?: boolean;
    [key: string]: unknown;
};

export type FeedQuestionData = Question & {
    answer_count?: number;
    answers?: { count?: number | null }[] | null;
    [key: string]: unknown;
};

export type FeedItem =
    | { type: 'article' | 'blog' | 'experiment' | 'book-review' | 'term'; data: FeedArticleData; sortDate: string; }
    | { type: 'question'; data: FeedQuestionData; sortDate: string; };

interface UnifiedFeedProps {
    items: FeedItem[];
    suggestedUsers?: any[];
    showExtras?: boolean;
}

export function UnifiedFeed({ items: initialItems, suggestedUsers = [], showExtras = true }: UnifiedFeedProps) {
    const [items, setItems] = useState<FeedItem[]>(initialItems);
    const [pendingItems, setPendingItems] = useState<FeedItem[]>([]);
    const [loading, setLoading] = useState(false);
    const [hasMore, setHasMore] = useState(true);
    const [beforeDate, setBeforeDate] = useState<string>(
        initialItems.length > 0 ? initialItems[initialItems.length - 1].sortDate : new Date().toISOString()
    );

    const [supabase] = useState(() => createClient());
    const observerRef = useRef<HTMLDivElement>(null);

    // Dynamic Cursor Pagination Fetcher
    const loadMoreItems = useCallback(async () => {
        if (loading || !hasMore) return;

        setLoading(true);
        try {
            const articleSelect = '*, author:profiles!articles_author_id_fkey(full_name, username, avatar_url, is_writer)';

            // Keyset Pagination: Fetch items older than the current cursor date (beforeDate)
            const [articlesResult, questionsResult] = await Promise.all([
                supabase
                    .from('articles')
                    .select(articleSelect)
                    .eq('status', 'published')
                    .lt('created_at', beforeDate)
                    .order('created_at', { ascending: false })
                    .limit(6),
                supabase
                    .from('questions')
                    .select('id, title, content, created_at, category, votes, tags, author:profiles(username, full_name, avatar_url, is_verified), answers(count)')
                    .lt('created_at', beforeDate)
                    .order('created_at', { ascending: false })
                    .limit(6)
            ]);

            const articles = (articlesResult.data || []) as unknown as FeedArticleData[];
            const questions = (questionsResult.data || []) as unknown as FeedQuestionData[];

            if (articles.length === 0 && questions.length === 0) {
                setHasMore(false);
                setLoading(false);
                return;
            }

            const processedNewItems = processFeedData(articles, questions);

            if (processedNewItems.length > 0) {
                setItems(prev => {
                    // Prevent duplicate elements
                    const existingIds = new Set(prev.map(item => `${item.type}-${item.data.id}`));
                    const uniqueNewItems = processedNewItems.filter(item => !existingIds.has(`${item.type}-${item.data.id}`));
                    return [...prev, ...uniqueNewItems];
                });

                // Advance the cursor date to the last processed item date
                setBeforeDate(processedNewItems[processedNewItems.length - 1].sortDate);
            } else {
                setHasMore(false);
            }
        } catch (error) {
            console.error("Failed to load more feed items:", error);
        } finally {
            setLoading(false);
        }
    }, [beforeDate, hasMore, loading, supabase]);

    // Intersection Observer setup for automatic loading on scroll
    useEffect(() => {
        const observerTarget = observerRef.current;
        if (!observerTarget || !hasMore) return;

        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting && !loading && hasMore) {
                    loadMoreItems();
                }
            },
            { rootMargin: "250px 0px" }
        );

        observer.observe(observerTarget);
        return () => {
            if (observerTarget) observer.unobserve(observerTarget);
        };
    }, [loadMoreItems, hasMore, loading]);

    // Supabase Real-time Listener (Twitter/Instagram style "New Posts" notification)
    useEffect(() => {
        const articleSelect = '*, author:profiles!articles_author_id_fkey(full_name, username, avatar_url, is_writer)';

        const channel = supabase
            .channel("realtime-feed-updates")
            // 1. Listen for new articles
            .on(
                "postgres_changes",
                { event: "INSERT", schema: "public", table: "articles" },
                async (payload) => {
                    const newArticleRow = payload.new;
                    if (newArticleRow && newArticleRow.status === 'published') {
                        // Fetch relation data (author details) which is not sent in raw real-time inserts
                        const { data: fullArticle } = await supabase
                            .from('articles')
                            .select(articleSelect)
                            .eq('id', newArticleRow.id)
                            .single();

                        if (fullArticle) {
                            const processed = processFeedData([fullArticle as unknown as FeedArticleData], []);
                            if (processed.length > 0) {
                                setPendingItems(prev => {
                                    const exists = prev.some(item => `${item.type}-${item.data.id}` === `${processed[0].type}-${processed[0].data.id}`);
                                    return exists ? prev : [processed[0], ...prev];
                                });
                            }
                        }
                    }
                }
            )
            // 2. Listen for new forum questions
            .on(
                "postgres_changes",
                { event: "INSERT", schema: "public", table: "questions" },
                async (payload) => {
                    const newQuestionRow = payload.new;
                    if (newQuestionRow) {
                        const { data: fullQuestion } = await supabase
                            .from('questions')
                            .select('id, title, content, created_at, category, votes, tags, author:profiles(username, full_name, avatar_url, is_verified), answers(count)')
                            .eq('id', newQuestionRow.id)
                            .single();

                        if (fullQuestion) {
                            const processed = processFeedData([], [fullQuestion as unknown as FeedQuestionData]);
                            if (processed.length > 0) {
                                setPendingItems(prev => {
                                    const exists = prev.some(item => `${item.type}-${item.data.id}` === `${processed[0].type}-${processed[0].data.id}`);
                                    return exists ? prev : [processed[0], ...prev];
                                });
                            }
                        }
                    }
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [supabase]);

    // Prepend pending realtime posts to the feed and scroll to top smoothly
    const applyPendingItems = () => {
        if (pendingItems.length === 0) return;

        setItems(prev => {
            const existingIds = new Set(prev.map(item => `${item.type}-${item.data.id}`));
            const uniquePending = pendingItems.filter(item => !existingIds.has(`${item.type}-${item.data.id}`));
            return [...uniquePending, ...prev];
        });
        setPendingItems([]);

        // Twitter-like smooth scroll to top
        window.scrollTo({
            top: 0,
            behavior: "smooth"
        });
    };

    return (
        <div className="flex flex-col gap-4 sm:gap-6 relative">

            {/* FLOATING REAL-TIME BADGE (PILL) */}
            {pendingItems.length > 0 && (
                <div className="sticky top-20 z-50 flex justify-center w-full pointer-events-none">
                    <button
                        onClick={applyPendingItems}
                        className="pointer-events-auto flex items-center gap-2 px-4 py-2.5 rounded-full bg-[#FFBD2E] text-black border-[3px] border-black font-black uppercase text-xs sm:text-sm tracking-wider shadow-[4px_4px_0px_0px_#000] hover:translate-y-[2px] hover:shadow-[2px_2px_0px_0px_#000] active:translate-y-[4px] active:shadow-none transition-all animate-bounce"
                    >
                        <RefreshCw className="w-4 h-4 animate-spin-slow" />
                        Yeni Paylaşımlar Var! ({pendingItems.length})
                    </button>
                </div>
            )}

            <div className="flex flex-col gap-4 sm:gap-6">
                {items.map((item, index) => (
                    <div
                        key={`${item.type}-${item.data.id}`}
                        className="feed-item-appear will-change-transform"
                        style={{ 
                            animationDelay: index < 3 ? `${index * 50}ms` : undefined,
                            contentVisibility: index > 4 ? 'auto' : undefined,
                            containIntrinsicSize: index > 4 ? '0 450px' : undefined
                        }}
                    >
                        {(item.type === 'article' || item.type === 'blog') && (
                            <NeoArticleCard
                                article={item.data}
                                initialLikes={item.data.likes_count || 0}
                                initialComments={item.data.comments_count || 0}
                                initialIsLiked={item.data.is_liked}
                                initialIsBookmarked={item.data.is_bookmarked}
                                priority={index < 1}
                            />
                        )}

                        {item.type === 'experiment' && (
                            <ExperimentCard
                                article={item.data}
                                index={index}
                            />
                        )}

                        {item.type === 'book-review' && (
                            <BookReviewCard
                                article={{
                                    ...item.data,
                                    id: Number(item.data.id),
                                    excerpt: item.data.excerpt || null,
                                    content: item.data.content || "",
                                    cover_url: item.data.cover_url || null,
                                    author: item.data.author ? {
                                        username: item.data.author.username || null,
                                        full_name: item.data.author.full_name || null,
                                        avatar_url: item.data.author.avatar_url || null,
                                    } : null
                                }}
                                index={index}
                            />
                        )}

                        {item.type === 'term' && (
                            <TermCard
                                article={{
                                    ...item.data,
                                    content: item.data.content || undefined,
                                    excerpt: item.data.excerpt || null,
                                    summary: item.data.summary || null,
                                    author: item.data.author ? {
                                        full_name: item.data.author.full_name || null,
                                        avatar_url: item.data.author.avatar_url || null,
                                    } : null
                                }}
                                index={index}
                            />
                        )}

                        {item.type === 'question' && (
