import { useState, useRef, useEffect } from "react";
import { Message } from "@/app/mesajlar/actions";
import { useChat } from "@/hooks/use-chat";
import { MessageBubble } from "./message-bubble";
import { DateSeparator } from "./date-separator";
import { cn } from "@/lib/utils";
import {
    Send,
    Sparkles,
    X,
    Paperclip,
    Reply,
    Search,
    ArrowDown,
} from "lucide-react";
import { m as motion, AnimatePresence } from "framer-motion";
import { searchMessages } from "@/app/mesajlar/actions";

interface ChatWindowProps {
    conversationId: string;
    initialMessages: Message[];
    currentUserId: string;
    initialReactions?: Record<number, { reaction: string; count: number; myReaction: boolean }[]>;
    otherUserAvatar?: string | null;
}

export function ChatWindow({
    conversationId,
    initialMessages,
    currentUserId,
    initialReactions = {},
    otherUserAvatar,
}: ChatWindowProps) {
    const {
        messages,
        reactions,
        sending,
        replyTo,
        editingMessage,
        scrollRef,
        setReplyTo,
        setEditingMessage,
        handleSend,
        handleDelete,
        handleEdit,
        handleReact,
        scrollToBottom,
    } = useChat({
        conversationId,
        initialMessages,
        currentUserId,
        initialReactions,
    });

    const [inputText, setInputText] = useState("");
    const [isSearching, setIsSearching] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const [searchResults, setSearchResults] = useState<Message[]>([]);
    const [showScrollDown, setShowScrollDown] = useState(false);
    const textareaRef = useRef<HTMLTextAreaElement>(null);
    const searchInputRef = useRef<HTMLInputElement>(null);

    // Native CSS field-sizing: content handles auto-resize


    // Focus on reply
    useEffect(() => {
        if (replyTo && textareaRef.current) {
            textareaRef.current.focus();
        }
    }, [replyTo]);

