        if (editingMessage) {
            setInputText(editingMessage.content);
            textareaRef.current?.focus();
        }
    }, [editingMessage]);

    // Scroll detection
    useEffect(() => {
        const el = scrollRef.current;
        if (!el) return;

        const handleScroll = () => {
            const distanceFromBottom = el.scrollHeight - el.scrollTop - el.clientHeight;
            setShowScrollDown(distanceFromBottom > 200);
        };

        el.addEventListener("scroll", handleScroll);
        return () => el.removeEventListener("scroll", handleScroll);
    }, [scrollRef]);

    // Search handler
    useEffect(() => {
        if (!searchQuery.trim()) {
            setSearchResults([]);
            return;
        }

        const timer = setTimeout(async () => {
            const results = await searchMessages(conversationId, searchQuery);
            setSearchResults(results);
        }, 300);

        return () => clearTimeout(timer);
    }, [searchQuery, conversationId]);

    const onSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!inputText.trim()) return;

        if (editingMessage) {
            handleEdit(editingMessage.id, inputText);
            setInputText("");
        } else {
            handleSend(inputText);
            setInputText("");
        }
    };

    // Group messages by date
    const groupedMessages: { date: string; messages: Message[] }[] = [];
    let currentDate = "";

    for (const msg of messages) {
        const msgDate = new Date(msg.created_at).toDateString();
        if (msgDate !== currentDate) {
            currentDate = msgDate;
            groupedMessages.push({ date: msg.created_at, messages: [msg] });
        } else {
            groupedMessages[groupedMessages.length - 1].messages.push(msg);
        }
    }

    return (
        <div className="flex flex-col h-[calc(100dvh-56px)] w-full bg-[#050505] font-[family-name:var(--font-outfit)] relative overflow-hidden">
            {/* Ambient gradient */}
            <div className="absolute top-0 left-0 w-full h-[200px] bg-gradient-to-b from-[#FACC15]/[0.03] to-transparent pointer-events-none z-0" />
            <div className="absolute bottom-0 left-0 w-full h-[100px] bg-gradient-to-t from-[#050505] to-transparent pointer-events-none z-[5]" />

            {/* Search Bar (toggleable) */}
            <AnimatePresence>
                {isSearching && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="border-b border-white/[0.06] bg-zinc-900/50 backdrop-blur-xl overflow-hidden z-20"
                    >
                        <div className="flex items-center gap-2 px-4 py-2.5">
                            <Search className="w-4 h-4 text-zinc-500 shrink-0" />
                            <input
                                ref={searchInputRef}
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                placeholder="Mesajlarda ara..."
                                className="flex-1 bg-transparent text-white text-sm placeholder:text-zinc-500 focus:outline-none"
                                autoFocus
                            />
                            <button
                                onClick={() => {
                                    setIsSearching(false);
                                    setSearchQuery("");
                                    setSearchResults([]);
                                }}
                                className="text-zinc-400 hover:text-white p-1"
                            >
                                <X className="w-4 h-4" />
                            </button>
                        </div>
                        {searchResults.length > 0 && (
                            <div className="max-h-40 overflow-y-auto border-t border-white/[0.04] px-4 py-2 space-y-1">
                                {searchResults.map((r) => (
                                    <div
                                        key={r.id}
                                        className="text-[13px] text-zinc-300 bg-zinc-800/40 rounded-lg px-3 py-2 cursor-pointer hover:bg-zinc-800/80 transition-colors"
                                    >
                                        <p className="truncate">{r.content}</p>
                                        <span className="text-[10px] text-zinc-500">
                                            {new Date(r.created_at).toLocaleDateString("tr-TR")}
                                        </span>
                                    </div>
                                ))}
                            </div>
                        )}
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Messages Area */}
            <div
                ref={scrollRef}
                className="flex-1 overflow-y-auto scroll-smooth z-10 pb-4"
            >
                {messages.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center space-y-5 opacity-60 px-8">
                        <div className="relative">
                            <div className="w-20 h-20 bg-gradient-to-br from-zinc-800 to-zinc-900 rounded-2xl flex items-center justify-center shadow-2xl transform rotate-3 border border-white/[0.06]">
                                <Sparkles className="w-8 h-8 text-[#FACC15]" />
                            </div>
                            <div className="absolute -inset-2 blur-2xl bg-[#FACC15]/10 -z-10 rounded-full" />
                        </div>
                        <div className="text-center">
                            <h3 className="font-black text-xl text-white tracking-tight mb-1.5">
                                Sohbeti Başlat
                            </h3>
                            <p className="text-zinc-500 font-medium text-sm max-w-[240px]">
                                Bu sohbetteki ilk mesajı sen gönder.
                            </p>
                        </div>
                    </div>
                ) : (
                    groupedMessages.map((group, gi) => (
                        <div key={gi}>
                            <DateSeparator date={group.date} />
                            {group.messages.map((msg, mi) => {
                                const isMe = msg.sender_id === currentUserId;
                                const prevMsg = mi > 0 ? group.messages[mi - 1] : null;
                                const nextMsg = mi < group.messages.length - 1 ? group.messages[mi + 1] : null;
                                const isFirst = !prevMsg || prevMsg.sender_id !== msg.sender_id;
                                const isLast = !nextMsg || nextMsg.sender_id !== msg.sender_id;
                                const msgReactions = reactions[msg.id] || [];

                                return (
                                    <MessageBubble
                                        key={msg.id}
                                        message={msg}
                                        isMe={isMe}
                                        isFirstInSequence={isFirst}
                                        isLastInSequence={isLast}
                                        reactions={msgReactions}
                                        currentUserId={currentUserId}
                                        otherUserAvatar={otherUserAvatar}
                                        onReply={(m) => setReplyTo(m)}
                                        onDelete={handleDelete}
                                        onEdit={(m) => setEditingMessage(m)}
                                        onReact={handleReact}
                                    />
                                );
                            })}
                        </div>
                    ))
                )}
            </div>

            {/* Scroll to bottom FAB */}
            <AnimatePresence>
                {showScrollDown && (
                    <motion.button
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.8 }}
                        onClick={() => scrollToBottom()}
                        className="absolute bottom-24 right-4 z-20 w-10 h-10 bg-zinc-800 border border-zinc-700 rounded-full flex items-center justify-center text-zinc-300 hover:bg-zinc-700 hover:text-white transition-all shadow-lg"
                    >
                        <ArrowDown className="w-4 h-4" />
                    </motion.button>
                )}
            </AnimatePresence>

            {/* Reply Preview */}
            <AnimatePresence>
                {replyTo && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="bg-zinc-900/80 backdrop-blur-xl border-t border-white/[0.06] overflow-hidden z-20"
                    >
                        <div className="flex items-center gap-3 px-4 py-2.5">
                            <div className="w-1 h-8 bg-[#FACC15] rounded-full shrink-0" />
                            <div className="flex-1 min-w-0">
                                <span className="text-[11px] font-bold text-[#FACC15]">
                                    <Reply className="w-3 h-3 inline mr-1" />
                                    {replyTo.sender_id === currentUserId ? "Kendine yanıt" : "Yanıtla"}
                                </span>
                                <p className="text-[13px] text-zinc-400 truncate">{replyTo.content}</p>
                            </div>
                            <button
                                onClick={() => setReplyTo(null)}
                                className="text-zinc-500 hover:text-white p-1 shrink-0"
                            >
                                <X className="w-4 h-4" />
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Edit Preview */}
            <AnimatePresence>
                {editingMessage && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="bg-zinc-900/80 backdrop-blur-xl border-t border-white/[0.06] overflow-hidden z-20"
                    >
                        <div className="flex items-center gap-3 px-4 py-2.5">
                            <div className="w-1 h-8 bg-blue-500 rounded-full shrink-0" />
                            <div className="flex-1">
                                <span className="text-[11px] font-bold text-blue-400">Mesaj düzenleniyor</span>
                                <p className="text-[13px] text-zinc-400 truncate">{editingMessage.content}</p>
                            </div>
                            <button
                                onClick={() => {
                                    setEditingMessage(null);
                                    setInputText("");
                                }}
                                className="text-zinc-500 hover:text-white p-1"
                            >
                                <X className="w-4 h-4" />
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Input Area */}
            <form
                onSubmit={onSubmit}
                className="p-3 bg-[#0a0a0a]/95 backdrop-blur-xl border-t border-white/[0.06] sticky bottom-0 z-20 safe-area-bottom"
            >
                <div className="max-w-4xl mx-auto flex items-end gap-2.5">
                    {/* Attachment */}
                    <button
                        type="button"
                        className="p-2.5 text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800/50 rounded-xl transition-all shrink-0 mb-0.5"
                    >
                        <Paperclip className="w-5 h-5" />
                    </button>

                    {/* Input */}
                    <div
                        className={cn(
                            "flex-1 bg-zinc-900/80 border border-zinc-800 rounded-[22px] flex items-end transition-all",
                            "hover:border-zinc-700 focus-within:border-[#FACC15]/40 focus-within:shadow-[0_0_0_1px_rgba(250,204,21,0.1)]",
                            editingMessage && "border-blue-500/30 focus-within:border-blue-500/50"
                        )}
                    >
                        <textarea
                            ref={textareaRef}
                            value={inputText}
                            onChange={(e) => setInputText(e.target.value)}
                            onKeyDown={(e) => {
                                if (e.key === "Enter" && !e.shiftKey) {
                                    e.preventDefault();
                                    onSubmit(e);
                                }
                                if (e.key === "Escape") {
                                    setReplyTo(null);
                                    setEditingMessage(null);
                                    setInputText("");
                                }
                            }}
                            placeholder={editingMessage ? "Mesajı düzenle..." : "Mesaj yaz..."}
                            className="w-full bg-transparent text-white placeholder:text-zinc-500 text-[14.5px] font-medium focus:outline-none py-3 px-4 max-h-32 min-h-[44px] resize-none leading-relaxed [field-sizing:content]"
                            rows={1}
                        />
                    </div>

                    {/* Send Button */}
                    <button
                        type="submit"
                        disabled={!inputText.trim() || sending}
                        className={cn(
                            "h-11 w-11 shrink-0 rounded-full flex items-center justify-center transition-all mb-0.5",
                            "disabled:opacity-30 disabled:scale-100 disabled:shadow-none",
                            editingMessage
                                ? "bg-blue-500 text-white shadow-[0_4px_12px_rgba(59,130,246,0.3)] hover:scale-105 active:scale-95"
                                : "bg-[#FACC15] text-black shadow-[0_4px_12px_rgba(250,204,21,0.25)] hover:scale-105 active:scale-95"
                        )}
                    >
                        <Send
                            className={cn(
                                "w-[18px] h-[18px] ml-0.5 stroke-[2.5px]",
                                sending && "animate-pulse"
                            )}
                        />
                    </button>
                </div>
            </form>
        </div>
    );
}

"use client";

import { Button } from "@/components/ui/button";
import { MessageCircle } from "lucide-react";
import { startConversation } from "@/app/mesajlar/actions";
import { toast } from "sonner";
import { useState } from "react";
import { useRouter } from "next/navigation";

interface StartChatButtonProps {
    otherUserId: string;
}

export function StartChatButton({ otherUserId }: StartChatButtonProps) {
    const [loading, setLoading] = useState(false);
    const router = useRouter();

    const handleStartChat = async () => {
        setLoading(true);
        try {
            const result = await startConversation(otherUserId);
            if (!result?.success && result?.error) {
                toast.error(result.error);
            } else if (result?.success && result?.conversationId) {
                router.push(`/mesajlar/${result.conversationId}`);
            }
        } catch (error) {
            toast.error("Bir hata oluştu.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <Button
            onClick={handleStartChat}
            disabled={loading}
            size="icon"
            variant="secondary"
            className="rounded-full h-10 w-10 bg-[#FACC15]/10 hover:bg-[#FACC15]/20 text-[#FACC15] border-0 shadow-sm transition-all hover:scale-105 active:scale-95"
            title="Mesaj Gönder"
        >
            <MessageCircle className="h-5 w-5" />
            <span className="sr-only">Mesaj Gönder</span>
        </Button>
    );
}

"use client";

import { useRef, useEffect, useState, useCallback } from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { RotateCcw, Play, Pause, Volume2, VolumeX, Rocket } from "lucide-react";
import confetti from "canvas-confetti";

// Game constants
const GRAVITY = 0.05;
const THRUST_POWER = 0.15;
const ROTATION_SPEED = 0.07;
const DRAG = 0.99; // Air resistance simulation
const SHIP_SIZE = 20;

// Types
interface Vector2D {
    x: number;
    y: number;
}

interface Particle {
    x: number;
    y: number;
    vx: number;
    vy: number;
    life: number;
    maxLife: number;
    color: string;
    size: number;
}

interface Bullet {
    x: number;
    y: number;
    vx: number;
    vy: number;
    life: number; // Frames to live
}

interface Enemy {
    id: number;
    x: number;
    y: number;
    radius: number;
    type: 'turret' | 'floater';
    health: number;
    active: boolean; // Is it on screen/active?
    lastFire: number;
}

export function SpaceBomberGame() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // Game State
    const [gameState, setGameState] = useState<'idle' | 'playing' | 'paused' | 'gameover' | 'victory'>('idle');
    const [score, setScore] = useState(0);
    const [fuel, setFuel] = useState(100);
    const [health, setHealth] = useState(100);
    const [level, setLevel] = useState(1);

    // Physics State Refs
    const shipPos = useRef<Vector2D>({ x: 100, y: 100 });
    const shipVel = useRef<Vector2D>({ x: 0, y: 0 });
    const shipAngle = useRef<number>(-Math.PI / 2); // Pointing up originally
    const particles = useRef<Particle[]>([]);
    const bullets = useRef<Bullet[]>([]);
    const enemyBullets = useRef<Bullet[]>([]); // New: Enemies shoot back
    const enemies = useRef<Enemy[]>([]);
    const keys = useRef<{ [key: string]: boolean }>({});
    const animationFrameId = useRef<number>(0);
    const lastTime = useRef<number>(0);

    // Camera
    const camera = useRef<Vector2D>({ x: 0, y: 0 });

    // Terrain Generation (Simple heightmap for now)
    const terrainPoints = useRef<Vector2D[]>([]);

    const initLevel = useCallback((lvl: number) => {
        // Generate Terrain
        const points: Vector2D[] = [];
        const width = 5000; // Long level
        let y = 500;

        // Floor
        points.push({ x: 0, y: 1000 }); // Bottom-left anchor
        points.push({ x: 0, y: y }); // Start point

        for (let x = 0; x < width; x += 50) {
            // Perlin-ish noise
            const noise = Math.sin(x * 0.01) * 50 + Math.sin(x * 0.05) * 20;
            y = 500 + noise;
            points.push({ x, y });
        }

        points.push({ x: width, y: 1000 }); // Bottom-right anchor
        terrainPoints.current = points;

        // Generate Enemies
        enemies.current = [];
        const enemyCount = 5 + lvl * 2;
        for (let i = 0; i < enemyCount; i++) {
            const x = 500 + Math.random() * (width - 600);
            const groundY = 500 + (Math.sin(x * 0.01) * 50 + Math.sin(x * 0.05) * 20); // Rough ground position approximation

            enemies.current.push({
                id: i,
                x: x,
                y: groundY - 30 - Math.random() * 200, // Float above ground
                radius: 15,
                type: Math.random() > 0.5 ? 'turret' : 'floater',
                health: 3,
                active: true,
                lastFire: 0
            });
        }

        // Reset Ship
        shipPos.current = { x: 100, y: 300 };
        shipVel.current = { x: 0, y: 0 };
        shipAngle.current = -Math.PI / 2;
        setFuel(100);
        setHealth(100);
        bullets.current = [];
        enemyBullets.current = [];
        particles.current = [];
    }, []);

    const createExplosion = (x: number, y: number, color: string, count: number) => {
        for (let i = 0; i < count; i++) {
            particles.current.push({
                x, y,
                vx: (Math.random() - 0.5) * 5,
                vy: (Math.random() - 0.5) * 5,
                life: 30 + Math.random() * 20,
                maxLife: 50,
                color,
                size: Math.random() * 3 + 1
            });
        }
    };

    // Main Game Loop
    const update = useCallback((time: number) => {
        if (gameState !== 'playing') return;

        const dt = (time - lastTime.current) / 16.67; // Normalize to ~60fps
        lastTime.current = time;

        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Ensure canvas has size (Fallback)
        if (canvas.width === 0 || canvas.height === 0) {
            if (containerRef.current) {
                canvas.width = containerRef.current.clientWidth || 800;
                canvas.height = 600;
            } else {
                canvas.width = 800;
                canvas.height = 600;
            }
        }

        // --- PHYSICS UPDATE ---

        // Ship Rotation
        if (keys.current['ArrowLeft'] || keys.current['a'] || keys.current['A']) shipAngle.current -= ROTATION_SPEED * dt;
        if (keys.current['ArrowRight'] || keys.current['d'] || keys.current['D']) shipAngle.current += ROTATION_SPEED * dt;

        // Ship Thrust
        const thrusting = keys.current['ArrowUp'] || keys.current['w'] || keys.current['W'];
        if (thrusting && fuel > 0) {
            shipVel.current.x += Math.cos(shipAngle.current) * THRUST_POWER * dt;
            shipVel.current.y += Math.sin(shipAngle.current) * THRUST_POWER * dt;
            setFuel(f => Math.max(0, f - 0.1 * dt));

            // Thrust Particles
            particles.current.push({
                x: shipPos.current.x - Math.cos(shipAngle.current) * 15,
                y: shipPos.current.y - Math.sin(shipAngle.current) * 15,
                vx: (Math.random() - 0.5) + shipVel.current.x * 0.5,
                vy: (Math.random() - 0.5) + shipVel.current.y * 0.5,
                life: 10,
                maxLife: 10,
                color: '#ffaa00',
                size: 2
            });
        }

        // Gravity & Drag
        shipVel.current.y += GRAVITY * dt;
        shipVel.current.x *= DRAG;
        shipVel.current.y *= DRAG;

        // Update Position
        shipPos.current.x += shipVel.current.x * dt;
        shipPos.current.y += shipVel.current.y * dt;

        // --- COLLISION DETECTION (TERRAIN) ---
        const tPoints = terrainPoints.current;
        const segmentIndex = Math.floor(shipPos.current.x / 50) + 1; // +1 because of anchor point

        if (tPoints && tPoints.length > 0 && segmentIndex >= 0 && segmentIndex < tPoints.length - 2) {
            const p1 = tPoints[segmentIndex];
            const p2 = tPoints[segmentIndex + 1];

            if (p1 && p2) {
                // Interpolate ground height at ship X
                const t = (shipPos.current.x - p1.x) / (p2.x - p1.x);
                const groundY = p1.y + t * (p2.y - p1.y);

                if (shipPos.current.y + SHIP_SIZE > groundY) {
                    // Ground Collision
                    const speed = Math.sqrt(shipVel.current.x ** 2 + shipVel.current.y ** 2);
                    if (speed > 4) {
                        // Crash
                        createExplosion(shipPos.current.x, shipPos.current.y, 'orange', 50);
                        setHealth(0);
                        setGameState('gameover');
                    } else {
                        // Land / Bounce
                        shipPos.current.y = groundY - SHIP_SIZE;
                        shipVel.current.y *= -0.3; // Bounce
                        shipVel.current.x *= 0.8; // Friction

                        // Slightly damage if bumpy landing
                        if (speed > 2) setHealth(h => Math.max(0, h - 5));
                    }
                }
            }
        }

        // Ceiling / sky collision
        if (shipPos.current.y < -500) {
            shipPos.current.y = -500;
            shipVel.current.y = 0;
        }


        // --- BULLETS ---
        if (keys.current[' '] && !keys.current['fired']) {
            bullets.current.push({
                x: shipPos.current.x + Math.cos(shipAngle.current) * 20,
                y: shipPos.current.y + Math.sin(shipAngle.current) * 20,
                vx: shipVel.current.x + Math.cos(shipAngle.current) * 15,
                vy: shipVel.current.y + Math.sin(shipAngle.current) * 15,
                life: 60
            });
            keys.current['fired'] = true; // Prevent rapid fire, require release
        }
        if (!keys.current[' ']) keys.current['fired'] = false;

        bullets.current.forEach(b => {
            b.x += b.vx * dt;
            b.y += b.vy * dt;
            b.life -= dt;
        });
        bullets.current = bullets.current.filter(b => b.life > 0);


        // --- ENEMIES ---
        enemies.current.forEach(enemy => {
            if (!enemy.active) return;

            // Simple AI: Turrets shoot if player is close
            const dx = shipPos.current.x - enemy.x;
            const dy = shipPos.current.y - enemy.y;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < 600 && Math.random() < 0.01) {
                // Shoot at player (Simple leading)
                const angle = Math.atan2(dy, dx);
                enemyBullets.current.push({
                    x: enemy.x,
                    y: enemy.y,
                    vx: Math.cos(angle) * 5,
                    vy: Math.sin(angle) * 5,
                    life: 100
                });
            }

            // Check collision with Player Bullets
            bullets.current.forEach((b, bIdx) => {
                const bdx = b.x - enemy.x;
                const bdy = b.y - enemy.y;
                if (Math.sqrt(bdx * bdx + bdy * bdy) < enemy.radius + 5) {
                    // Hit enemy
                    enemy.health--;
                    b.life = 0; // Destroy bullet
                    createExplosion(enemy.x, enemy.y, '#aa00ff', 5);
                    if (enemy.health <= 0) {
                        enemy.active = false;
                        setScore(s => s + 100);
                        createExplosion(enemy.x, enemy.y, '#00ff88', 30);

                        // Victory Check
                        if (enemies.current.filter(e => e.active).length === 0) {
                            confetti({
                                particleCount: 150,
                                spread: 70,
                                origin: { y: 0.6 }
                            });
                            setGameState('victory');
                        }
                    }
                }
            });
        });

        // --- ENEMY BULLETS ---
        enemyBullets.current.forEach(b => {
            b.x += b.vx * dt;
            b.y += b.vy * dt;
            b.life -= dt;

            // Hit player?
            const dx = b.x - shipPos.current.x;
            const dy = b.y - shipPos.current.y;
            if (Math.sqrt(dx * dx + dy * dy) < SHIP_SIZE) {
                setHealth(h => Math.max(0, h - 10));
                b.life = 0;
                createExplosion(shipPos.current.x, shipPos.current.y, 'red', 5);
                if (health <= 0) setGameState('gameover');
            }
        });
        enemyBullets.current = enemyBullets.current.filter(b => b.life > 0);


        // --- PARTICLES ---
        particles.current.forEach(p => {
            p.x += p.vx * dt;
            p.y += p.vy * dt;
            p.life -= dt;
            p.vx *= 0.95;
            p.vy *= 0.95;
        });
        particles.current = particles.current.filter(p => p.life > 0);


        // --- CAMERA ---
        // Smoothly follow ship
        const targetCamX = shipPos.current.x - canvas.width / 2;
        const targetCamY = shipPos.current.y - canvas.height / 2;

        if (!isNaN(targetCamX) && !isNaN(targetCamY)) {
            camera.current.x += (targetCamX - camera.current.x) * 0.1;
            camera.current.y += (targetCamY - camera.current.y) * 0.1;
        }

        // --- RENDER ---
        ctx.fillStyle = '#0f0f15';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.save();
        ctx.translate(-camera.current.x, -camera.current.y);

        // Draw Background Grid
        ctx.strokeStyle = '#1e1e2f';
        ctx.lineWidth = 1;
        const gridSize = 100;

        const offsetX = Math.floor(camera.current.x / gridSize) * gridSize;
        const offsetY = Math.floor(camera.current.y / gridSize) * gridSize;

        ctx.beginPath();
        for (let gx = offsetX; gx < offsetX + canvas.width + gridSize; gx += gridSize) {
            ctx.moveTo(gx, offsetY - gridSize);
            ctx.lineTo(gx, offsetY + canvas.height + gridSize);
        }
        for (let gy = offsetY; gy < offsetY + canvas.height + gridSize; gy += gridSize) {
            ctx.moveTo(offsetX - gridSize, gy);
            ctx.lineTo(offsetX + canvas.width + gridSize, gy);
        }
        ctx.stroke();


        // Draw Terrain
        ctx.fillStyle = '#2c2c3e';
        ctx.strokeStyle = '#6c5ce7';
        ctx.lineWidth = 3;
        ctx.beginPath();
        if (tPoints.length > 0) {
            ctx.moveTo(tPoints[0].x, tPoints[0].y);
            for (let i = 1; i < tPoints.length; i++) {
                ctx.lineTo(tPoints[i].x, tPoints[i].y);
            }
        }
        ctx.fill();
        ctx.stroke();

        // Draw Player Ship
        if (health > 0) {
            ctx.save();
            ctx.translate(shipPos.current.x, shipPos.current.y);
            ctx.rotate(shipAngle.current + Math.PI / 2);

            ctx.strokeStyle = '#00d2d3';
            ctx.lineWidth = 2;
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.moveTo(0, -15);
            ctx.lineTo(10, 10);
            ctx.lineTo(0, 5);
            ctx.lineTo(-10, 10);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            ctx.fillStyle = '#54a0ff';
            ctx.beginPath();
            ctx.arc(0, -2, 3, 0, Math.PI * 2);
            ctx.fill();

            ctx.restore();
        }

        // Draw Bullets
        ctx.fillStyle = '#ff9ff3';
        bullets.current.forEach(b => {
            ctx.fillRect(b.x - 2, b.y - 2, 4, 4);
        });

        // Draw Enemy Bullets
        ctx.fillStyle = '#ff4757';
        enemyBullets.current.forEach(b => {
            ctx.beginPath();
            ctx.arc(b.x, b.y, 3, 0, Math.PI * 2);
            ctx.fill();
        });

        // Draw Enemies
        enemies.current.forEach(e => {
            if (!e.active) return;
            ctx.fillStyle = e.type === 'turret' ? '#ff6b6b' : '#feca57';
            ctx.beginPath();
            if (e.type === 'turret') {
                ctx.rect(e.x - 10, e.y - 10, 20, 20);
            } else {
                ctx.moveTo(e.x, e.y - 15);
                ctx.lineTo(e.x + 15, e.y);
                ctx.lineTo(e.x, e.y + 15);
                ctx.lineTo(e.x - 15, e.y);
            }
            ctx.fill();

            // Health bar
            ctx.fillStyle = 'red';
            ctx.fillRect(e.x - 15, e.y - 25, 30, 4);
            ctx.fillStyle = 'green';
            ctx.fillRect(e.x - 15, e.y - 25, 30 * (e.health / 3), 4);
        });

        // Draw Particles
        particles.current.forEach(p => {
            ctx.globalAlpha = p.life / p.maxLife;
            ctx.fillStyle = p.color;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        });
        ctx.globalAlpha = 1;

        ctx.restore();

        animationFrameId.current = requestAnimationFrame(() => update(performance.now()));
    }, [gameState]);

    // Handle Input
    useEffect(() => {
        const handleDown = (e: KeyboardEvent) => {
            if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", " "].indexOf(e.code) > -1) {
                e.preventDefault();
            }
            keys.current[e.key] = true;
        };
        const handleUp = (e: KeyboardEvent) => { keys.current[e.key] = false; };

        window.addEventListener('keydown', handleDown);
        window.addEventListener('keyup', handleUp);
        return () => {
            window.removeEventListener('keydown', handleDown);
            window.removeEventListener('keyup', handleUp);
        };
    }, []);

    // Handle Start
    const startGame = () => {
        // console.log("Starting game...");
        initLevel(level);
        setGameState('playing');
        lastTime.current = performance.now();
        setTimeout(() => {
            if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
            update(performance.now());
        }, 50);
    };

    // On Mount Resize
    useEffect(() => {
        const resize = () => {
            if (canvasRef.current && containerRef.current) {
                canvasRef.current.width = containerRef.current.clientWidth || 800;
                canvasRef.current.height = 600;
            }
        };
        resize();
        window.addEventListener('resize', resize);

        // Initial setup for background
        initLevel(1);

        return () => {
            window.removeEventListener('resize', resize);
            cancelAnimationFrame(animationFrameId.current);
        }
    }, [initLevel]);


    return (
        <Card className="p-4 border-2 border-primary/20 bg-background overflow-hidden relative" ref={containerRef}>

            {/* HUD */}
            <div className="flex justify-between items-center mb-4">
                <div className="flex gap-4">
                    <div className="flex flex-col">
                        <span className="text-[10px] uppercase font-bold text-muted-foreground">Skor</span>
                        <span className="text-xl font-mono font-bold text-primary">{score}</span>
                    </div>
                    <div className="flex flex-col w-32">
                        <span className="text-[10px] uppercase font-bold text-muted-foreground">Yakıt</span>
                        <div className="h-4 w-full bg-secondary rounded-full overflow-hidden border border-border">
                            <div className="h-full bg-orange-500 transition-all duration-100" style={{ width: `${fuel}%` }} />
                        </div>
                    </div>
                    <div className="flex flex-col w-32">
                        <span className="text-[10px] uppercase font-bold text-muted-foreground">Zırh</span>
                        <div className="h-4 w-full bg-secondary rounded-full overflow-hidden border border-border">
                            <div className="h-full bg-red-500 transition-all duration-100" style={{ width: `${health}%` }} />
                        </div>
                    </div>
                </div>

                <div className="text-right">
                    <div className="text-xs text-muted-foreground">GRAVITY WARRIOR</div>
                    <div className="text-xs text-primary font-bold">LEVEL {level}</div>
                </div>
            </div>

            <canvas
                ref={canvasRef}
                className="w-full bg-black rounded-lg border border-border shadow-inner focus:outline-none"
                style={{ height: '600px' }}
                width={800} // Explicit fallback
                height={600}
                tabIndex={0} // Ensure it can receive focus
            />

            {/* Overlays */}
            {gameState === 'idle' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/80 z-10 p-6 text-center">
                    <Rocket className="w-16 h-16 text-primary mb-4 animate-bounce" />
                    <h1 className="text-4xl font-black text-white mb-2">GRAVITY WARRIOR</h1>
                    <p className="text-gray-300 mb-8 max-w-md">
                        Gerçek fizik kuralları geçerlidir.<br />
                        <span className="text-primary font-bold">W / YUKARI</span> ile motorları çalıştır.<br />
                        <span className="text-primary font-bold">A / D / YÖN</span> ile gemiyi döndür.<br />
                        <span className="text-primary font-bold">SPACE</span> ile ateş et.
                    </p>
                    <Button size="lg" className="text-lg font-bold brutalist-button" onClick={startGame}>
                        <Play className="mr-2 w-5 h-5" /> GÖREVİ BAŞLAT
                    </Button>
                </div>
            )}

            {gameState === 'gameover' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-red-900/80 z-10 p-6 text-center">
                    <h2 className="text-5xl font-black text-white mb-4">GÖREV BAŞARISIZ</h2>
                    <p className="text-white mb-8 text-xl">Aracı parçaladın!</p>
                    <Button size="lg" variant="destructive" className="text-lg font-bold" onClick={startGame}>
                        <RotateCcw className="mr-2 w-5 h-5" /> TEKRAR DENE
                    </Button>
                </div>
            )}

            {gameState === 'victory' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-green-900/90 z-10 p-6 text-center">
                    <div className="mb-4 text-6xl">🏆</div>
                    <h2 className="text-4xl font-black text-white mb-2">BÖLGE TEMİZLENDİ!</h2>
                    <p className="text-white/80 mb-6">Mükemmel uçuş, pilot.</p>
                    <div className="flex gap-4">
                        <Button size="lg" className="bg-white text-green-900 hover:bg-gray-200 font-bold" onClick={() => { setLevel(l => l + 1); startGame(); }}>
                            SONRAKİ SEVİYE
                        </Button>
                    </div>
                </div>
            )}

            {/* Mobile Controls Hint */}
            <div className="absolute bottom-4 left-4 text-white/30 text-xs pointer-events-none md:block hidden">
                KLAVYE KONTROLLERİ AKTİF
            </div>
        </Card>
    );
}

