            twitter: twitter || null,
            github: github || null,
            instagram: instagram || null,
            linkedin: linkedin || null
        };

        const result = await updateProfile({
            full_name: fullName,
            bio,
            avatar_url: avatarUrl,
            website: website || undefined,
            social_links: socialLinks
