"use client";

import { useState, useTransition } from "react";
import { Button } from "@/components/ui/button";
import { followUser, unfollowUser } from "@/app/profil/actions";
import { toast } from "sonner";
import { UserPlus, UserMinus, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";

interface FollowButtonProps {
    targetUserId: string;
    initialIsFollowing: boolean;
    targetUsername?: string;
    variant?: string;
    className?: string;
}

export function FollowButton({ targetUserId, initialIsFollowing, targetUsername, variant, className }: FollowButtonProps) {
    const [isFollowing, setIsFollowing] = useState(initialIsFollowing);
    const [isPending, startTransition] = useTransition();

    const handleFollowToggle = () => {
        startTransition(async () => {
            // Optimistic update
            const previousState = isFollowing;
            setIsFollowing(!previousState);

            try {
                let result;
                if (previousState) {
                    result = await unfollowUser(targetUserId);
                } else {
                    result = await followUser(targetUserId);
                }

                if (!result.success) {
                    // Revert on failure
                    setIsFollowing(previousState);
                    toast.error(result.error || "İşlem başarısız.");
                } else {
                    if (!previousState) {
                        // Just followed
                        if (targetUsername === 'barannnbozkurttb') {
                            toast.success("Gönüllerin sultanı Hazreti Admin'i takip ediyorsun! 👑");
                        } else {
                            toast.success("Takip ediliyor.");
                        }
                    } else {
                        toast.success("Takipten çıkıldı.");
                    }
                }
            } catch (error) {
                setIsFollowing(previousState);
                toast.error("Bir hata oluştu.");
            }
        });
    };

    return (
        <Button
            variant={isFollowing ? "outline" : "default"}
            className={cn(
                "gap-2 transition-all duration-300",
                isFollowing
                    ? "border-zinc-300 hover:bg-red-50 hover:text-red-600 hover:border-red-200 dark:border-zinc-700 dark:hover:bg-red-900/20"
                    : "bg-blue-600 hover:bg-blue-700 text-white shadow-md hover:shadow-lg hover:-translate-y-0.5",
                className
            )}
            onClick={handleFollowToggle}
            disabled={isPending}
        >
            {isPending ? (
                <Loader2 className="h-4 w-4 animate-spin" />
            ) : isFollowing ? (
                <>
                    <UserMinus className="h-4 w-4" />
                    Takibi Bırak
                </>
            ) : (
                <>
                    <UserPlus className="h-4 w-4" />
                    Takip Et
                </>
            )}
        </Button>
    );
}

"use client";

import { useState, useCallback } from "react";
import Cropper from "react-easy-crop";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Loader2 } from "lucide-react";
import getCroppedImg from "@/lib/crop-image";

interface ImageCropperDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    imageSrc: string | null;
    aspectRatio: number; // 1 for avatar, 16/9 for cover etc.
    onCropComplete: (croppedImageBlob: Blob) => void;
}

export function ImageCropperDialog({ open, onOpenChange, imageSrc, aspectRatio, onCropComplete }: ImageCropperDialogProps) {
    const [crop, setCrop] = useState({ x: 0, y: 0 });
    const [zoom, setZoom] = useState(1);
    const [croppedAreaPixels, setCroppedAreaPixels] = useState<any>(null);
    const [loading, setLoading] = useState(false);

    const onCropChange = (crop: { x: number; y: number }) => {
        setCrop(crop);
    };

    const onZoomChange = (zoom: number) => {
        setZoom(zoom);
    };

    const onCropCompleteInternal = useCallback((croppedArea: any, croppedAreaPixels: any) => {
        setCroppedAreaPixels(croppedAreaPixels);
    }, []);

    const handleSave = async () => {
        if (!imageSrc || !croppedAreaPixels) return;
        setLoading(true);
        try {
            const croppedImage = await getCroppedImg(imageSrc, croppedAreaPixels);
            if (croppedImage) {
                onCropComplete(croppedImage);
            }
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
            onOpenChange(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent
                className="sm:max-w-xl bg-zinc-950 border-zinc-800 text-white p-0 overflow-hidden gap-0 fixed left-[50%] top-[50%] translate-x-[-50%] translate-y-[-50%]"
                style={{ transform: "translate(-50%, -50%)" }}
            >
                <DialogHeader className="p-4 border-b border-zinc-800 bg-zinc-950 z-10">
                    <DialogTitle>Medyayı Düzenle</DialogTitle>
                </DialogHeader>

                <div className="relative h-[400px] w-full bg-black">
                    {imageSrc && (
                        <Cropper
                            image={imageSrc}
                            crop={crop}
                            zoom={zoom}
                            aspect={aspectRatio}
                            onCropChange={onCropChange}
                            onCropComplete={onCropCompleteInternal}
                            onZoomChange={onZoomChange}
                        />
                    )}
                </div>

                <div className="p-4 bg-zinc-950 space-y-4">
                    <div className="flex items-center gap-4">
                        <span className="text-xs font-bold text-zinc-500">ZOOM</span>
                        <input
                            type="range"
                            min={1}
                            max={3}
                            step={0.1}
                            value={zoom}
                            onChange={(e) => setZoom(parseFloat(e.target.value))}
                            className="flex-1 accent-[#FFC800] h-2 bg-zinc-800 rounded-lg appearance-none cursor-pointer"
                        />
                    </div>
                </div>

                <DialogFooter className="p-4 pt-0 bg-zinc-950">
                    <Button variant="ghost" onClick={() => onOpenChange(false)} disabled={loading}>
                        İptal
                    </Button>
                    <Button onClick={handleSave} disabled={loading} className="bg-[#FFC800] text-black hover:bg-[#FFC800]/90">
                        {loading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                        Uygula
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase";
import { Card, CardContent } from "@/components/ui/card";
import { Bell, MessageCircle, Star, Award } from "lucide-react";
import Link from "next/link";
import { formatDistanceToNow } from "date-fns";
import { tr } from "date-fns/locale";
import { cn } from "@/lib/utils";

interface Notification {
    id: number;
    type: string;
    content: string;
    is_read: boolean;
    created_at: string;
    resource_id: string;
    resource_type: string;
}

export function NotificationsList({ userId }: { userId: string }) {
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [loading, setLoading] = useState(true);
    // Fix: Initialize supabase client once
    const [supabase] = useState(() => createClient());

    useEffect(() => {
        const fetchNotifications = async () => {
            const { data } = await supabase
                .from('notifications')
                .select('*')
                .eq('recipient_id', userId)
                .order('created_at', { ascending: false });

            if (data) {
                setNotifications(data);
            }
            setLoading(false);
        };

        fetchNotifications();

        // Subscribe to new notifications
        const channel = supabase
            .channel('notifications')
            .on(
                'postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'notifications',
                    filter: `recipient_id=eq.${userId}`
                },
                (payload) => {
                    setNotifications(prev => [payload.new as Notification, ...prev]);
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [userId]);

    const getIcon = (type: string) => {
        switch (type) {
            case 'new_answer':
            case 'new_comment_reply':
            case 'reply':
            case 'comment':
                return <MessageCircle className="h-5 w-5 text-blue-500" />;
            case 'badge_earned':
                return <Award className="h-5 w-5 text-yellow-500" />;
            case 'new_vote':
            case 'like':
                return <Star className="h-5 w-5 text-orange-500" />;
            case 'report':
                return <Bell className="h-5 w-5 text-red-500" />;
            default:
                return <Bell className="h-5 w-5 text-gray-500" />;
        }
    };

    const getNotificationLink = (notification: Notification) => {
        switch (notification.type) {
            case 'follow':
                // We might need actor username here, but if we don't have it joined, we can link to profile root or handle it.
                // For now, let's assume resource_id might be the username or id.
                // If resource_type is profile, resource_id is likely the user id.
                // Without a join, we can't easily get the username. 
                // Let's fallback to /profil for now or if resource_id is username.
                return `/profil`;
            case 'like':
            case 'comment':
            case 'reply':
            case 'new_answer':
            case 'new_comment_reply':
            case 'new_vote':
                if (notification.resource_type === 'question') return `/forum/${notification.resource_id}`;
                if (notification.resource_type === 'article') return `/makale/${notification.resource_id}`;
                return '#';
            case 'welcome':
                return '/profil';
            case 'report':
                return '/admin?tab=reports';
            default:
                return '#';
        }
    };

    if (loading) {
        return <div className="text-center py-8 text-muted-foreground">Bildirimler yükleniyor...</div>;
    }

    if (notifications.length === 0) {
        return (
            <div className="text-center py-12 border rounded-xl bg-muted/10 border-dashed">
                <Bell className="h-12 w-12 mx-auto mb-4 text-muted-foreground/20" />
                <p className="text-muted-foreground">Henüz bildiriminiz yok.</p>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            {notifications.map((notification) => (
                <Link prefetch={false} href={getNotificationLink(notification)} key={notification.id} className="block">
                    <Card className={cn(
                        "transition-colors hover:bg-muted/50",
                        !notification.is_read && "bg-primary/5 border-primary/20"
                    )}>
                        <CardContent className="p-4 flex items-start gap-4">
                            <div className="mt-1 bg-background p-2 rounded-full border shadow-sm">
                                {getIcon(notification.type)}
                            </div>
                            <div className="flex-1">
                                <p className="text-sm font-medium leading-none mb-1.5">
                                    {notification.content}
                                </p>
                                <p className="text-xs text-muted-foreground">
                                    {formatDistanceToNow(new Date(notification.created_at), { addSuffix: true, locale: tr })}
                                </p>
                            </div>
                            {!notification.is_read && (
                                <div className="h-2 w-2 rounded-full bg-primary mt-2" />
                            )}
                        </CardContent>
                    </Card>
                </Link>
            ))}
        </div>
    );
}

