                        {profile?.is_verified && (
                            <div className="absolute bottom-0 right-0 bg-blue-500 text-white p-0.5 rounded-full border-2 border-white shadow-sm" title="Onaylı">
                                <BadgeCheck className="w-5 h-5" />
                            </div>
                        )}
