                                            currentBio={profile.bio}
                                            currentAvatarUrl={profile.avatar_url}
                                            currentWebsite={profile.website}
                                            currentSocialLinks={profile.social_links}
                                            currentUsername={profile.username}
                                            userEmail={user?.email}
                                        />
                                    ) : (
                                        user && (
