        "Tebrikler, NASA seni arıyor.",
        "Zeka fışkırıyor resmen!",
        "Bu kadar zeki olmak yormuyor mu?"
    ];

    const NEGATIVE_MESSAGES = [
        "Salla kazan tutmadı be gülüm.",
        "Newton mezarında ters döndü.",
        "Fizikle aran biraz limoni galiba.",
        "Bunu bilmemek ayıp değil, öğrenmemek ayıp (şaka şaka ayıp).",
        "Atma recep din kardeşiyiz.",
        "Biraz daha çalışman lazım, çok değil, baya.",
        "Üzgünüm ama cevap şıkkı bile sana güldü.",
        "Belki de fizik senin olayım değildir?",
        "Yanlış cevap vererek de tarihe geçebilirsin.",
        "Kitabı tersten mi okudun?",
        "Olsun, en azından denedin... sanırım.",
        "Cevabı salladın ama tutmadı di mi?"
    ];

    const handleStart = () => {
        setIsStarted(true);
    };

    const handleOptionSelect = (value: string) => {
        if (isAnswered) return;
        setSelectedOption(parseInt(value));
    };

    const handleCheckAnswer = () => {
        if (selectedOption === null) return;

        const isCorrect = selectedOption === currentQuestion.correct_answer;
        if (isCorrect) {
            setScore(prev => prev + 1);
            setFeedback(POSITIVE_MESSAGES[Math.floor(Math.random() * POSITIVE_MESSAGES.length)]);
            confetti({
                particleCount: 50,
                spread: 60,
                origin: { y: 0.7 }
            });
        } else {
            setFeedback(NEGATIVE_MESSAGES[Math.floor(Math.random() * NEGATIVE_MESSAGES.length)]);
        }

        setIsAnswered(true);
    };

    const handleNextQuestion = () => {
        if (currentQuestionIndex < questions.length - 1) {
            setCurrentQuestionIndex(prev => prev + 1);
            setSelectedOption(null);
            setIsAnswered(false);
            setFeedback("");
        } else {
            finishQuiz();
        }
    };

    const finishQuiz = async () => {
        setIsFinished(true);
        // Sarcastic Confetti for high scores
        if (score > questions.length / 2) {
            const end = Date.now() + 1000;
            const colors = ['#bb0000', '#ffffff'];
            (function frame() {
                confetti({
                    particleCount: 2,
                    angle: 60,
                    spread: 55,
                    origin: { x: 0 },
                    colors: colors
                });
                confetti({
                    particleCount: 2,
                    angle: 120,
                    spread: 55,
                    origin: { x: 1 },
                    colors: colors
                });

                if (Date.now() < end) {
                    requestAnimationFrame(frame);
                }
            }());
        }

        try {
            const result = await submitQuizResult(quizId, score, questions.length);
            if (result.success) {
                setPointsEarned(result.pointsEarned || 0);
                setAlreadyCompleted(!!result.alreadyCompleted);
            }
        } catch (error) {
            console.error("Failed to submit result", error);
        }
    };

    if (!isStarted) {
        return (
            <div className="container max-w-3xl py-12 px-4 mx-auto min-h-[60vh] flex flex-col justify-center items-center">
                <Card className="w-full text-center p-8 border-4 border-black dark:border-white shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] dark:shadow-[8px_8px_0px_0px_rgba(255,255,255,1)]">
                    <CardHeader className="space-y-4">
                        <Badge className="mx-auto text-base py-1 px-4 border-2 border-black dark:border-white bg-primary text-primary-foreground hover:bg-primary shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] dark:shadow-[4px_4px_0px_0px_rgba(255,255,255,1)] -rotate-2">
                            FİZİK TESTİ
                        </Badge>
                        <h1 className="text-3xl md:text-5xl font-black uppercase tracking-tighter">
                            {title}
                        </h1>
                        <p className="text-lg text-muted-foreground font-medium max-w-2xl mx-auto leading-relaxed">
                            {description}
                        </p>
                    </CardHeader>
                    <CardFooter className="justify-center pt-6">
                        <Button
                            onClick={handleStart}
                            size="lg"
                            className="text-lg font-black px-10 py-6 bg-black text-white hover:bg-black/90 dark:bg-white dark:text-black dark:hover:bg-white/90 border-2 border-transparent hover:scale-105 transition-transform shadow-xl"
                        >
                            <Play className="mr-3 h-5 w-5 fill-current" />
                            TESTE BAŞLA
                        </Button>
                    </CardFooter>
                </Card>
            </div>
        );
    }

    if (isFinished) {
        const percentage = (score / questions.length) * 100;
        const isSuccess = percentage > 50;
        const isPerfect = score === questions.length;

        let titleText = "Helal Olsun!";
        if (!isSuccess) titleText = "Geçmiş Olsun!";
        if (isPerfect) titleText = "İnanılmaz!";

        let messageText = "";
        if (isPerfect) messageText = "Hatasız kul olmaz derler ama sen oldun! Mükemmelsin.";
        else if (isSuccess) messageText = "Ortalamanın üstündesin, havanı atabilirsin. (Ama çok değil)";
        else messageText = "Fizik kitabının kapağını hiç açmayı denedin mi? Merak ettim sadece.";

        return (
            <div className="container max-w-md py-8 px-4 mx-auto">
                <Card className="w-full text-center p-4 border-4 border-black dark:border-white shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] dark:shadow-[8px_8px_0px_0px_rgba(255,255,255,1)] overflow-hidden relative">
                    <CardHeader className="pb-2">
                        <motion.div
                            initial={{ scale: 0, rotate: -180 }}
                            animate={{ scale: 1, rotate: 0 }}
                            transition={{ type: "spring", stiffness: 260, damping: 20 }}
                            className={`mx-auto p-4 rounded-full mb-4 ring-4 ring-black dark:ring-white shadow-xl ${isSuccess ? 'bg-yellow-400' : 'bg-red-400'}`}
                        >
                            {isSuccess ?
                                <motion.div
                                    animate={{ rotate: [0, -10, 10, -10, 10, 0] }}
                                    transition={{ duration: 1.5, repeat: Infinity, delay: 1 }}
                                >
                                    <Trophy className="h-12 w-12 text-black" />
                                </motion.div>
                                :
                                <motion.div
                                    animate={{ y: [0, 5, 0, 5, 0] }}
                                    transition={{ duration: 2, repeat: Infinity, repeatDelay: 1 }}
                                >
                                    <ThumbsDown className="h-12 w-12 text-black" />
                                </motion.div>
                            }
                        </motion.div>
                        <CardTitle className="text-2xl md:text-3xl font-black uppercase transform -rotate-1">
                            {titleText}
                        </CardTitle>
                    </CardHeader>

                    <CardContent className="space-y-6 relative z-10 pb-2">
                        <div className="space-y-1">
                            <div className="text-6xl font-black tracking-tighter tabular-nums">
                                {score}<span className="text-2xl text-muted-foreground">/{questions.length}</span>
                            </div>
                        </div>

                        <div className="p-3 bg-muted/50 rounded-xl border-2 border-black/10 dark:border-white/10">
                            <p className="font-bold text-base leading-snug">
                                {messageText}
                            </p>
                        </div>

                        {/* Points Display */}
                        {pointsEarned > 0 && (
                            <motion.div
                                initial={{ y: 20, opacity: 0 }}
                                animate={{ y: 0, opacity: 1 }}
                                transition={{ delay: 0.5 }}
                                className="flex items-center justify-center gap-2 bg-green-100 dark:bg-green-900/30 border-2 border-green-600 p-3 rounded-xl text-green-800 dark:text-green-100"
                            >
                                <PartyPopper className="h-5 w-5" />
                                <span className="text-lg font-black">{pointsEarned} HubPuan Kazandın!</span>
                            </motion.div>
                        )}

                        {(alreadyCompleted || (!alreadyCompleted && pointsEarned === 0 && score > 0)) && (
                            <div className="text-xs font-bold text-muted-foreground bg-muted p-2 rounded-lg relative overflow-hidden group">
                                <span className="relative z-10">(Daha önce çözdüğün için tekrar puan yok çakal 😉)</span>
                            </div>
                        )}
                    </CardContent>

                    <CardFooter className="flex flex-col gap-2 pt-2">
                        <Button
                            onClick={() => window.location.reload()}
                            className="w-full border-2 border-black font-bold h-10 text-base shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-none transition-all"
                        >
                            <RotateCcw className="mr-2 h-4 w-4" />
                            Tekrar Dene
                        </Button>
                        <Link prefetch={false} href="/testler" className="w-full">
                            <Button variant="outline" className="w-full border-2 font-bold h-10 text-base">Testlere Dön</Button>
                        </Link>
                    </CardFooter>
                </Card>
            </div>
        );
    }

    return (
        <div className="w-full max-w-xl mx-auto space-y-4 pt-4 pb-12">
            <div className="flex justify-between items-center px-2">
                <span className="font-bold text-muted-foreground uppercase tracking-widest text-xs">
                    Soru {currentQuestionIndex + 1} / {questions.length}
                </span>
                <div className="flex items-center gap-2 font-black text-base bg-black text-white px-2 py-0.5 rounded-md -rotate-2 shadow-lg">
                    <Trophy className="h-3 w-3 text-yellow-400" />
                    <span>{score}</span>
                </div>
            </div>

            <div className="h-2 w-full bg-secondary border-2 border-black dark:border-white rounded-full overflow-hidden">
                <div
                    className="h-full bg-primary transition-all duration-500 ease-out"
                    style={{ width: `${progress}%` }}
                />
            </div>

            <Card className="mt-2 border-4 border-black dark:border-white shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] dark:shadow-[6px_6px_0px_0px_rgba(255,255,255,1)] rounded-xl overflow-hidden relative">
                <CardHeader className="bg-secondary/30 border-b-2 border-black dark:border-white p-4">
                    <CardTitle className="text-lg md:text-xl font-black leading-tight selection:bg-primary selection:text-white">
                        {currentQuestion.question_text}
                    </CardTitle>
                </CardHeader>
                <CardContent className="p-4 space-y-4">
                    <RadioGroup
                        key={currentQuestion.id} // Forces reset on new question
                        value={selectedOption?.toString()}
                        onValueChange={handleOptionSelect}
                        className="space-y-2"
                    >
                        <AnimatePresence mode="popLayout">
                            {currentQuestion.options.map((option, index) => {
                                let itemStyle = "border-2 border-black dark:border-white bg-card hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-none shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] dark:shadow-[2px_2px_0px_0px_rgba(255,255,255,1)]";
                                if (isAnswered) {
                                    if (index === currentQuestion.correct_answer) {
                                        itemStyle = "border-2 border-green-600 bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-100 scale-[1.01]";
                                    } else if (index === selectedOption && index !== currentQuestion.correct_answer) {
                                        itemStyle = "border-2 border-red-600 bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-100 opacity-80";
                                    } else {
                                        itemStyle = "border-2 opacity-40 grayscale border-dashed";
                                    }
                                } else if (selectedOption === index) {
                                    itemStyle = "border-2 border-primary bg-primary/10 ring-2 ring-primary ring-offset-2 shadow-[1px_1px_0px_0px_rgba(0,0,0,1)]";
                                }

                                return (
                                    <motion.div
                                        key={index}
                                        initial={{ opacity: 0, x: -10 }}
                                        animate={{ opacity: 1, x: 0 }}
                                        transition={{ delay: index * 0.05 }}
                                    >
                                        <div className={`flex items-center space-x-3 rounded-lg p-2.5 cursor-pointer transition-all duration-200 ${itemStyle}`}>
                                            <RadioGroupItem
                                                value={index.toString()}
                                                id={`option-${index}`}
                                                disabled={isAnswered}
                                                className="w-4 h-4 border-2 border-black data-[state=checked]:bg-primary data-[state=checked]:text-black"
                                            />
                                            <Label
                                                htmlFor={`option-${index}`}
                                                className="flex-1 cursor-pointer font-bold text-sm leading-snug"
                                            >
                                                {option}
                                            </Label>
                                            {isAnswered && index === currentQuestion.correct_answer && (
                                                <CheckCircle2 className="h-5 w-5 text-green-600" />
                                            )}
                                        </div>
                                    </motion.div>
                                );
                            })}
                        </AnimatePresence>
                    </RadioGroup>

                    {/* Feedback Message - Made smaller and less intrusive */}
                    <AnimatePresence>
                        {feedback && (
                            <motion.div
                                initial={{ opacity: 0, y: 10, scale: 0.9 }}
                                animate={{ opacity: 1, y: 0, scale: 1 }}
                                exit={{ opacity: 0, scale: 0.9 }}
                                className={`p-3 rounded-lg text-center font-bold text-sm text-white transform -rotate-1 shadow-md ${selectedOption === currentQuestion.correct_answer ? 'bg-green-500' : 'bg-red-500'
                                    }`}
                            >
                                {feedback}
                            </motion.div>
                        )}
                    </AnimatePresence>

                    {/* Action Button - Compact */}
                    <div className="pt-1">
                        {!isAnswered ? (
                            <Button
                                onClick={handleCheckAnswer}
                                disabled={selectedOption === null}
                                className="w-full h-10 text-base font-black uppercase tracking-wider border-2 border-black shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-none transition-all"
                            >
                                Cevabı Kontrol Et
                            </Button>
                        ) : (
                            <Button
                                onClick={handleNextQuestion}
                                className="w-full h-10 text-base font-black uppercase tracking-wider border-2 border-black shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-none transition-all bg-zinc-900 text-white hover:bg-zinc-800"
                            >
                                {currentQuestionIndex < questions.length - 1 ? (
                                    <>
                                        Sıradaki
                                        <ArrowRight className="ml-2 h-4 w-4" />
                                    </>
                                ) : (
                                    "Sonuçlar"
                                )}
                            </Button>
                        )}
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase";
import { toast } from "sonner";
import { useRouter } from "next/navigation";

export function RealtimeProvider() {
  const [userId, setUserId] = useState<string | null>(null);
  const [supabase] = useState(() => createClient());
  const router = useRouter();

  useEffect(() => {
    // 1. Get initial session
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUserId(session?.user?.id || null);
    });

    // 2. Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUserId(session?.user?.id || null);
    });

    return () => {
      subscription.unsubscribe();
    };
  }, [supabase]);

  useEffect(() => {
    if (!userId) return;

    // 3. Subscribe to notifications table
    const channel = supabase
      .channel("user-notifications")
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "notifications",
          filter: `recipient_id=eq.${userId}`,
        },
        (payload) => {
          const notification = payload.new;

          // Show toast notification
          toast("Yeni Bildirim!", {
            description: "Biri seninle etkileşime geçti. İncelemek için tıkla.",
            action: {
              label: "Görüntüle",
              onClick: () => router.push("/notifications"),
            },
          });

          // Optionally trigger a router refresh to update the notification counter in the header
          router.refresh();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [userId, supabase, router]);

  return null;
}

"use client";

import { useState } from "react";
import { Flag } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { createClient } from "@/lib/supabase";
import { toast } from "sonner";

interface ReportButtonProps {
    contentType: "question" | "answer" | "article" | "comment";
    contentId: number;
    variant?: "ghost" | "outline" | "default";
    size?: "sm" | "default";
}

const REPORT_REASONS = [
    { value: "spam", label: "Spam veya reklam" },
    { value: "offensive", label: "Hakaret veya saldırgan içerik" },
    { value: "misinformation", label: "Yanlış bilgi" },
    { value: "duplicate", label: "Tekrar eden içerik" },
    { value: "other", label: "Diğer" },
];

export function ReportButton({ contentType, contentId, variant = "ghost", size = "sm" }: ReportButtonProps) {
    const [open, setOpen] = useState(false);
    const [reason, setReason] = useState("");
    const [description, setDescription] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);
    // Fix: Initialize supabase client once
    const [supabase] = useState(() => createClient());

    const handleSubmit = async () => {
        if (!reason) {
            toast.error("Lütfen bir sebep seçin");
            return;
        }

        setIsSubmitting(true);

        try {
            const { data: { user } } = await supabase.auth.getUser();

            if (!user) {
                toast.error("Rapor göndermek için giriş yapmalısınız");
                setIsSubmitting(false);
                return;
            }

            const { error } = await supabase
                .from("reports")
                .insert({
                    reporter_id: user.id,
                    content_type: contentType,
                    content_id: contentId,
                    reason: reason,
                    description: description || null
                });

            if (error) throw error;

            toast.success("Raporunuz alındı. İnceleme yapılacak.");
            setOpen(false);
            setReason("");
            setDescription("");
        } catch (error: any) {
            console.error("Report error:", error);
            toast.error("Bir hata oluştu");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button variant={variant} size={size} className="gap-1.5 h-9 px-3 rounded-lg border-[2px] border-black dark:border-zinc-600 bg-white dark:bg-zinc-800 text-black dark:text-zinc-300 font-bold text-xs uppercase tracking-wider shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.08)] hover:bg-neo-pink hover:text-white hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-[1px_1px_0_0_#000] transition-all">
                    <Flag className="h-3.5 w-3.5 stroke-[2.5px]" />
                    <span className="hidden sm:inline">Rapor</span>
                </Button>
            </DialogTrigger>
            <DialogContent className="sm:max-w-md border-[2.5px] border-black dark:border-zinc-700 rounded-[10px] shadow-[6px_6px_0_0_#000] dark:shadow-[6px_6px_0_0_rgba(255,255,255,0.06)] bg-white dark:bg-[#1e1e21]">
                <DialogHeader>
                    <DialogTitle>İçeriği Rapor Et</DialogTitle>
                    <DialogDescription>
                        Bu içeriği bildirmenizin sebebi nedir?
                    </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-4">
                    <RadioGroup value={reason} onValueChange={setReason}>
                        {REPORT_REASONS.map((r) => (
                            <div key={r.value} className="flex items-center space-x-2">
                                <RadioGroupItem value={r.value} id={r.value} />
                                <Label htmlFor={r.value} className="cursor-pointer">
                                    {r.label}
                                </Label>
                            </div>
                        ))}
                    </RadioGroup>

                    <div className="space-y-2">
                        <Label htmlFor="description">Ek açıklama (opsiyonel)</Label>
                        <Textarea
                            id="description"
                            placeholder="Daha fazla detay ekleyin..."
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            rows={3}
                        />
                    </div>
                </div>
                <DialogFooter>
                    <Button variant="outline" onClick={() => setOpen(false)} className="border-[2px] border-black dark:border-zinc-600 rounded-lg font-bold shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.06)]">
                        İptal
                    </Button>
                    <Button onClick={handleSubmit} disabled={isSubmitting || !reason} className="bg-[#FFBD2E] text-black hover:bg-[#FFD268] border-[2px] border-black dark:border-zinc-600 rounded-lg font-bold shadow-[2px_2px_0_0_#000] dark:shadow-[2px_2px_0_0_rgba(255,255,255,0.06)] hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-[1px_1px_0_0_#000] transition-all">
                        {isSubmitting ? "Gönderiliyor..." : "Gönder"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState } from "react";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Flag } from "lucide-react";
import { toast } from "sonner";
import { createReport } from "@/app/actions/report";

interface ReportDialogProps {
    resourceId: string | number;
    resourceType: 'question' | 'answer' | 'comment' | 'user';
    trigger?: React.ReactNode;
}

export function ReportDialog({ resourceId, resourceType, trigger }: ReportDialogProps) {
    const [open, setOpen] = useState(false);
    const [reason, setReason] = useState("");
    const [description, setDescription] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!reason) {
            toast.error("Lütfen bir sebep seçin.");
            return;
        }

        setIsSubmitting(true);
        try {
            const result = await createReport({
                resourceId: resourceId.toString(),
                resourceType,
                reason,
                description
            });

            if (result.success) {
                toast.success("Şikayetiniz alındı. Teşekkürler.");
                setOpen(false);
                setReason("");
                setDescription("");
            } else {
                toast.error(result.error || "Bir hata oluştu.");
            }
        } catch (error) {
            toast.error("Bir hata oluştu.");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                {trigger || (
                    <Button variant="ghost" size="sm" className="text-muted-foreground hover:text-destructive">
                        <Flag className="h-4 w-4 mr-2" />
                        Bildir
                    </Button>
                )}
            </DialogTrigger>
            <DialogContent className="sm:max-w-[425px]">
                <DialogHeader>
                    <DialogTitle>İçeriği Bildir</DialogTitle>
                    <DialogDescription>
                        Bu içeriğin neden uygunsuz olduğunu düşünüyorsunuz?
                    </DialogDescription>
                </DialogHeader>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="space-y-2">
                        <Label htmlFor="reason">Sebep</Label>
                        <Select value={reason} onValueChange={setReason}>
                            <SelectTrigger>
                                <SelectValue placeholder="Bir sebep seçin" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="spam">Spam / Reklam</SelectItem>
                                <SelectItem value="harassment">Taciz / Zorbalık</SelectItem>
                                <SelectItem value="inappropriate">Uygunsuz İçerik</SelectItem>
                                <SelectItem value="misinformation">Yanlış Bilgi</SelectItem>
                                <SelectItem value="other">Diğer</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                    <div className="space-y-2">
                        <Label htmlFor="description">Açıklama (İsteğe bağlı)</Label>
                        <Textarea
                            id="description"
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            placeholder="Ek detaylar..."
                            className="resize-none"
                        />
                    </div>
                    <DialogFooter>
                        <Button type="button" variant="outline" onClick={() => setOpen(false)}>
                            İptal
                        </Button>
                        <Button type="submit" disabled={isSubmitting}>
                            {isSubmitting ? "Gönderiliyor..." : "Gönder"}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState } from "react";
import { m as motion, AnimatePresence } from "framer-motion";
import { X, Image as ImageIcon, Sparkles, Send, Palette } from "lucide-react";
import { createClient } from "@/lib/supabase";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import imageCompression from "browser-image-compression";
import NextImage from "next/image";

interface RapidScienceEditorModalProps {
    isOpen: boolean;
    onClose: () => void;
}

export function RapidScienceEditorModal({ isOpen, onClose }: RapidScienceEditorModalProps) {
    const [step, setStep] = useState<'guide' | 'editor'>('guide');
    const [title, setTitle] = useState("");
    const [summary, setSummary] = useState("");
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [imagePreview, setImagePreview] = useState<string | null>(null);
    const [selectedGradient, setSelectedGradient] = useState("from-amber-600 to-orange-600");
    const [isSubmitting, setIsSubmitting] = useState(false);

    const supabase = createClient();

    const gradients = [
        { name: "Kehribar", val: "from-amber-600 to-orange-600" },
        { name: "Kozmik", val: "from-blue-600 to-purple-600" },
        { name: "Zehir", val: "from-emerald-600 to-cyan-600" },
        { name: "Süpernova", val: "from-pink-600 to-rose-600" },
        { name: "Kara Delik", val: "from-gray-800 to-black" },
    ];

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];

            // Compression
            try {
                const options = {
                    maxSizeMB: 1,
                    maxWidthOrHeight: 1080,
                    useWebWorker: true
                };
                const compressedFile = await imageCompression(file, options);
                setImageFile(compressedFile);
                setImagePreview(URL.createObjectURL(compressedFile));
            } catch (err) {
                console.error(err);
                toast.error("Resim sıkıştırılamadı. Hay anasını ya tekrar dene olmazsa barana bildir");
            }
        }
    };

    const handleSubmit = async () => {
        if (!title || !imageFile) {
            toast.error("Başlık ve resim zorunludur hocam.");
            return;
        }

        setIsSubmitting(true);
        try {
            // 1. Upload Image
            const fileName = `story-${Date.now()}-${Math.random().toString(36).substring(7)}`;
            const { data: uploadData, error: uploadError } = await supabase.storage
                .from('article-images') // Reusing existing bucket for now
                .upload(`stories/${fileName}`, imageFile);

            if (uploadError) throw uploadError;

            // 2. Get Public URL
            const { data: publicUrlData } = supabase.storage
                .from('article-images')
                .getPublicUrl(`stories/${fileName}`);

            const imageUrl = publicUrlData.publicUrl;

            // 3. Insert into Table
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) throw new Error("Giriş yapmalısın.");

            // Get profile id
            const { data: profile } = await supabase.from('profiles').select('id, is_writer').eq('id', user.id).maybeSingle();
            if (!profile?.is_writer) throw new Error("Yazar yetkiniz yok. Bu araya nasıl ulaştın? Ulaşmaman lazımdı.");

            const { error: insertError } = await supabase
                .from('stories')
                .insert({
                    author_id: user.id,
                    title,
                    summary,
                    image_url: imageUrl,
                    color: selectedGradient
                });

            if (insertError) throw insertError;

            toast.success("Hızlı Bilim hikayesi paylaşıldı!");
            onClose();
            // Reset
            setStep('guide');
            setTitle("");
            setSummary("");
            setImageFile(null);
            setImagePreview(null);

            // Force reload to see new story (simple way)
            window.location.reload();

        } catch (error: any) {
            console.error(error);
            toast.error("Hata: " + error.message);
        } finally {
            setIsSubmitting(false);
        }
    };

    if (!isOpen) return null;

    return (
        <AnimatePresence>
            <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4"
            >
                <div onClick={onClose} className="absolute inset-0" /> {/* Backdrop click */}

                <motion.div
                    initial={{ scale: 0.9, y: 20 }}
                    animate={{ scale: 1, y: 0 }}
                    exit={{ scale: 0.9, y: 20 }}
                    className="relative w-full max-w-md bg-zinc-900 border border-white/10 rounded-3xl overflow-hidden shadow-2xl"
                >
                    <button onClick={onClose} className="absolute top-4 right-4 z-10 p-2 hover:bg-white/10 rounded-full transition-colors text-white/60 hover:text-white">
                        <X className="w-5 h-5" />
                    </button>

                    {/* Content Switcher */}
                    {step === 'guide' ? (
                        <div className="p-8 flex flex-col items-center text-center">
                            <div className="w-16 h-16 bg-gradient-to-tr from-amber-500 to-orange-600 rounded-2xl flex items-center justify-center mb-6 shadow-lg shadow-amber-900/20 rotate-3">
                                <Sparkles className="w-8 h-8 text-black" />
                            </div>
                            <h2 className="text-2xl font-bold text-white mb-3">Hızlı Bilim Nedir?</h2>
                            <p className="text-slate-400 mb-8 leading-relaxed">
                                Instagram hikayeleri gibi, hızlı tüketilen, görsel ağırlıklı ve çarpıcı bilimsel gerçekler.
                                <br /><br />
                                <ul className="text-left text-sm space-y-2 bg-white/5 p-4 rounded-xl border border-white/5">
                                    <li>⚡️ <b>Kısa & Öz:</b> En fazla 3 cümle.</li>
                                    <li>🎨 <b>Görsel Odaklı:</b> Dikey (9:16) görseller tercih et.</li>
                                    <li>🧪 <b>Bilimsel:</b> Kaynağı belli, net bilgi.</li>
                                </ul>
                            </p>
                            <Button
                                onClick={() => setStep('editor')}
                                className="w-full bg-white text-black hover:bg-zinc-200 font-bold h-12 rounded-xl"
                            >
                                Oluşturmaya Başla
                            </Button>
                        </div>
                    ) : (
                        <div className="p-6">
                            <h2 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                                <Sparkles className="w-5 h-5 text-amber-500" />
                                Hikaye Oluşturucu
                            </h2>

                            <div className="space-y-4">
                                {/* Image Upload & Preview */}
                                <div className="relative aspect-[9/16] w-full max-h-[300px] bg-black/50 border-2 border-dashed border-white/10 rounded-2xl overflow-hidden group cursor-pointer hover:border-amber-500/50 transition-colors">
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleImageUpload}
                                        className="absolute inset-0 opacity-0 cursor-pointer z-10"
                                    />
                                    {imagePreview ? (
                                        <NextImage src={imagePreview} alt="Preview" fill className="object-cover" />
                                    ) : (
                                        <div className="absolute inset-0 flex flex-col items-center justify-center text-white/40 group-hover:text-white transition-colors">
                                            <ImageIcon className="w-8 h-8 mb-2" />
                                            <span className="text-xs font-medium">Görsel Seç</span>
                                        </div>
                                    )}
                                    {/* Gradient Overlay Preview */}
                                    <div className={`absolute inset-0 bg-gradient-to-b ${selectedGradient} opacity-30 mix-blend-overlay pointer-events-none`} />
                                </div>

                                {/* Inputs */}
                                <div className="space-y-3">
                                    <Input
                                        placeholder="Çarpıcı Başlık (Örn: Işık Hızı?)"
                                        value={title}
                                        onChange={(e) => setTitle(e.target.value)}
                                        className="bg-black/20 border-white/10 text-white placeholder:text-white/20"
                                        maxLength={40}
                                    />
                                    <Textarea
                                        placeholder="Kısa Açıklama (Max 150 karakter)"
                                        value={summary}
                                        onChange={(e) => setSummary(e.target.value)}
                                        className="bg-black/20 border-white/10 text-white placeholder:text-white/20 h-20 resize-none"
                                        maxLength={150}
                                    />
                                </div>

                                {/* Gradient Picker */}
                                <div>
                                    <label className="text-xs text-white/40 mb-2 flex items-center gap-1">
                                        <Palette className="w-3 h-3" />
                                        Atmosfer Rengi
                                    </label>
                                    <div className="flex gap-2">
                                        {gradients.map((g) => (
                                            <button
                                                key={g.name}
                                                onClick={() => setSelectedGradient(g.val)}
                                                className={`w-8 h-8 rounded-full bg-gradient-to-br ${g.val} border-2 transition-all ${selectedGradient === g.val ? 'border-white scale-110' : 'border-transparent opacity-50 hover:opacity-100'}`}
                                                title={g.name}
                                            />
                                        ))}
                                    </div>
                                </div>

                                <Button
                                    onClick={handleSubmit}
                                    disabled={isSubmitting}
                                    className="w-full bg-amber-600 hover:bg-amber-500 text-white font-bold h-12 rounded-xl mt-4"
                                >
                                    {isSubmitting ? "Paylaşılıyor... Bekle lütfen hocam" : (
                                        <>
                                            Paylaş <Send className="w-4 h-4 ml-2" />
                                        </>
                                    )}
                                </Button>
                            </div>
                        </div>
                    )}
                </motion.div>
            </motion.div>
        </AnimatePresence>
    );
}

